window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch07"]={"id": "ch07", "title": "第七章 非编码RNA", "sub": "陈铭《生物信息学》第三版 · 科学出版社", "sub2": "复试生物信息学 · 逐章详解", "modules": [{"i": 0, "name": "第七章 非编码RNA", "slides": [{"i": 0, "sec": "第一节 非编码RNA概述", "title": "非编码RNA概述与基本特征", "notes": "本页引入非编码RNA（non-coding RNA, ncRNA）的概念：除mRNA外，生物体内还存在大量不编码蛋白质、直接在RNA水平发挥作用的RNA。细胞中含量最高的是rRNA和tRNA，广义ncRNA包括这两类，狭义ncRNA通常不包括。人类基因组约30亿碱基对中，蛋白质编码序列仅占1.5%，约75%的基因组序列可被转录为RNA，其中非编码RNA占总RNA的74%。这些ncRNA并非垃圾RNA，其突出和核心作用是调控。2006年诺贝尔生理学或医学奖授予Andrew Fire和Craig Mello，表彰他们发现RNA干扰（RNA interference, RNAi）现象。按碱基长度，ncRNA一般分为两类：短链非编码RNA（small ncRNA, sncRNA），长度一般小于200 nt，包括miRNA、piRNA、siRNA、snRNA、snoRNA等；长链非编码RNA（long non-coding RNA, lncRNA），长度一般大于200 nt，环状RNA（circular RNA, circRNA）也是一类特殊的长链非编码RNA。图7-1示意细胞内RNA的组成与分类关系。", "page": 134, "level": "掌握", "img": "assets/img/ch07/p134.jpg", "anim": null, "fig": null, "points": ["非编码RNA（ncRNA）不编码蛋白质，直接在RNA水平发挥作用", "广义ncRNA包括rRNA和tRNA，狭义ncRNA通常不包括", "人类基因组约30亿碱基对，蛋白质编码序列仅占1.5%", "约75%的基因组序列可转录为RNA，其中非编码RNA占很大比例", "⚠️ 考点/易错点：易混点：广义ncRNA包括rRNA和tRNA，狭义ncRNA通常不包括；核心考点是ncRNA并非垃圾RNA，其主要作用是调控。"], "code": null, "lang": null, "check": {"q": "关于非编码RNA（ncRNA）的基本特征，下列说法正确的是？", "o": ["A. 细胞中含量最高的是miRNA和siRNA", "B. 狭义ncRNA通常包括rRNA和tRNA", "C. 人类基因组中蛋白质编码序列约占1.5%，约75%的基因组序列可被转录为RNA", "D. ncRNA被称为垃圾RNA，不发挥调控作用"], "a": "C", "e": "细胞中含量最高的是rRNA和tRNA；广义ncRNA包括rRNA和tRNA，狭义通常不包括；ncRNA并非垃圾RNA，其突出和核心作用是调控。"}, "cards": [{"front": "非编码RNA的定义是什么？", "back": "不编码蛋白质、直接在RNA水平发挥作用的RNA。", "mnemonic": "不产蛋白，直接干活", "useImg": false}]}, {"i": 1, "sec": "第一节 非编码RNA概述", "title": "miRNA、lncRNA特征及非编码RNA识别", "notes": "本页重点介绍两类重要ncRNA。miRNA主要在转录后负调控目标基因表达，是最重要的一类调控小RNA；miRBase release 21已报道人类miRNA为2588个，预期总数还会增加，且癌症发展与miRNA相关，可用于人类癌症分类。lncRNA是当前研究热点，与许多染色质重塑复合物相关，通过定位这些复合物到特定基因位点改变DNA甲基化和组蛋白状态，在表观遗传调控中起重要作用；它不仅在转录水平，也在转录后水平调节蛋白质编码基因表达，参与细胞分化、个体发育等生命过程，异常表达与多种重大疾病相关。lncRNA存在带PolyA尾和不带PolyA尾两种形式，具有跨物种低保守性、组织特异性表达和丰度低等特点。保守估计哺乳动物基因组4%~9%的序列产生lncRNA转录本，而蛋白质编码RNA比例仅1%~5%。RNA调控网络可能决定复杂特性并在疾病中发挥作用。非编码RNA大规模鉴定主要有理论预测和实验方法；理论预测借助计算机从已知ncRNA提取特征信息，再全基因组搜索，较成功的软件包括snoScan、snoGPS、tRNAScan、mirScan、RNAz和RNAmotif等。", "page": 135, "level": "掌握", "img": "assets/img/ch07/p135.jpg", "anim": null, "fig": null, "points": ["miRNA主要在转录后负调控目标基因表达，是最重要的调控小RNA", "miRBase release 21报道人类miRNA为2588个，预期总数还会增加", "癌症发展与miRNA相关，可用于人类癌症分类", "lncRNA与染色质重塑复合物相关，通过定位改变DNA甲基化和组蛋白状态", "⚠️ 考点/易错点：考点：miRNA主要在转录后负调控靶基因，可用于癌症分类；lncRNA通过定位染色质重塑复合物参与表观遗传调控，是当前研究热点。"], "code": null, "lang": null, "check": {"q": "关于miRNA和lncRNA的特征，下列说法正确的是？", "o": ["A. miRNA主要在转录水平正调控目标基因表达", "B. miRBase release 21已报道人类miRNA为2588个，且癌症发展与miRNA相关", "C. lncRNA与染色质重塑复合物无关", "D. lncRNA只在转录后水平调节蛋白质编码基因表达"], "a": "B", "e": "miRNA主要在转录后负调控目标基因表达；lncRNA与许多染色质重塑复合物相关，在表观遗传调控中起重要作用，并可在转录和转录后水平调节基因表达。"}, "cards": [{"front": "miRNA的主要功能是什么？", "back": "在转录后负调控目标基因表达。", "mnemonic": "转录后刹车", "useImg": false}]}, {"i": 2, "sec": "第一节 非编码RNA概述", "title": "lncRNA相关常用资源数据库", "notes": "本页以表7-1形式列出lncRNA相关常用资源。NONCODE是目前最全面的lncRNA资源，提供17个物种（截至2017年11月）的非编码RNA数据，并支持序列比对等多种功能，网址http://www.noncode.org。LNCipedia包含人类超过14万条lncRNA注释信息，包括二级结构、编码潜能、miRNA结合位点等，网址https://lncipedia.org/。LncRNASNP2收集整理了超过14万人类lncRNA和超过11万小鼠lncRNA上的数百万条SNP信息，提供lncRNA突变功能、相关疾病、癌症样本表达等信息，网址http://bioinfo.life.hust.edu.cn/lncRNASNP2/。CANTATAdb提供10种模式植物lncRNA的表达信息等，网址http://yeti.amu.edu.pl/CANTATA/。HUGO-lncRNA提供已经官方定名的lncRNA Symbol，网址http://www.genenames.org/rna/LNCRNA。NPInter收集了22个物种非编码RNA之间以及非编码RNA与生物分子（DNA、RNA、蛋白质等）的互作关系，网址http://www.bioinfo.org/NPInter/。EVLncRNAs收录实验证实的lncRNA，覆盖414个物种，网址http://biophy.dzu.edu.cn/EVLncRNAs/。学习时应掌握各数据库的物种范围、核心数据类型和典型用途。", "page": 136, "level": "掌握", "img": "assets/img/ch07/p136.jpg", "anim": null, "fig": "表7-1列出lncRNA相关常用资源数据库，可查看数据库名称、网址和主要功能。", "points": ["NONCODE是最全面的lncRNA资源，提供17个物种数据，支持序列比对等功能", "LNCipedia包含人类超过14万条lncRNA注释信息，包括二级结构、编码潜能、miRNA结合位点等", "lncRNA相关常用资源数据库以表7-1形式列出", "⚠️ 考点/易错点：易混点：NONCODE是最全面的lncRNA资源（多物种），LNCipedia侧重人类lncRNA注释，LncRNASNP2侧重lncRNA相关SNP，注意数据库名称与功能对应。"], "code": null, "lang": null, "check": {"q": "关于lncRNA相关常用资源数据库，下列说法正确的是？", "o": ["A. NONCODE只提供人类lncRNA数据", "B. LNCipedia包含人类超过14万条lncRNA注释信息", "C. LncRNASNP2只收集小鼠lncRNA数据", "D. NONCODE不支持序列比对功能"], "a": "B", "e": "NONCODE提供17个物种的非编码RNA数据并支持序列比对等功能；LNCipedia包含人类超过14万条lncRNA注释信息；LncRNASNP2收集整理了超过14万人类lncRNA。"}, "cards": [{"front": "最全面的lncRNA资源数据库是哪个？", "back": "NONCODE。", "mnemonic": "非编码，找NONCODE", "useImg": false}]}, {"i": 3, "sec": "第一节 非编码RNA概述", "title": "非编码RNA的编码潜能与注释", "notes": "本页讨论非编码RNA可能具有编码潜能的现象。有研究发现某些lncRNA可翻译蛋白质或多肽，例如果蝇大脑中发现大量环状RNA翻译蛋白质或多肽。这种编码能力被忽视的原因包括：对circRNA等新RNA了解太少，可能存在不同翻译机制；现有预测手段未很好预测其编码潜能。可读框（ORF）可能存在于任何mRNA序列中，但很多ORF不翻译蛋白质；ORF越长翻译概率越大，传统ORF预测软件通常限制ORF发现长度，如不少于300 nt（可翻译为100 aa），导致长度小于100 aa的微肽无法被预测。标准实验手段也常漏过微小翻译产物：电泳中微肽早早跑到凝胶底部，质谱分析的清洗步骤会把分子质量不足的微肽清洗掉。目前通过对核糖体测序（Ribo-seq）等数据全面分析，越来越多非编码RNA被证实有编码潜能。这一发现使mRNA与非编码RNA界限变得模糊，ncRNA可能需要重新定义，实验手段也需革新。非编码RNA注释方面，基于计算方法可发现一些ncRNA基因，但主要集中在序列特征已很好表征的ncRNA；此后出现用户可定制的RNA基序搜索程序，并进一步完善了基于相关物种基因组序列比较、碱基组成特征、新的RNA序列比对和二级结构预测等方法。NONCODE是专用于非编码RNA（不包括tRNA和rRNA）的集成知识数据库。", "page": 137, "level": "掌握", "img": "assets/img/ch07/p137.jpg", "anim": null, "fig": null, "points": ["某些lncRNA可翻译蛋白质或多肽，例如果蝇大脑中环状RNA翻译蛋白质或多肽", "编码能力被忽视的原因包括对circRNA等新RNA了解太少，可能存在不同翻译机制", "现有预测手段未很好预测其编码潜能", "可读框（ORF）可能存在于任何mRNA序列中，但很多ORF不翻译蛋白质；ORF越长翻译概率越大", "⚠️ 考点/易错点：易错点：非编码RNA并非绝对不编码，某些lncRNA/circRNA可翻译多肽；ORF越长翻译概率越大，传统预测软件常限定ORF长度（如≥300 nt）。"], "code": null, "lang": null, "check": {"q": "关于非编码RNA的编码潜能与注释，下列说法正确的是？", "o": ["A. 所有lncRNA都不能翻译蛋白质或多肽", "B. 果蝇大脑中发现大量环状RNA翻译蛋白质或多肽", "C. 传统ORF预测软件通常不限制ORF发现长度", "D. ORF越短翻译概率越大"], "a": "B", "e": "某些lncRNA可翻译蛋白质或多肽，例如果蝇大脑中发现大量环状RNA翻译蛋白质或多肽；ORF越长翻译概率越大，传统ORF预测软件通常限制ORF发现长度，如不少于300 nt。"}, "cards": [{"front": "为什么某些lncRNA的编码潜能被忽视？", "back": "对circRNA等新RNA了解太少，可能存在不同翻译机制；现有预测手段未很好预测其编码潜能。", "mnemonic": "新RNA，老方法测不准", "useImg": false}]}, {"i": 4, "sec": "第一节 非编码RNA概述", "title": "非编码RNA按细胞内分布分类：snoRNA与snRNA", "notes": "本页进入第二节非编码RNA的分类，指出ncRNA因来源、性质和功能不同，可根据侧重点采用不同分类方法。按细胞内分布不同分类，首先介绍核仁小RNA（small nucleolar RNA, snoRNA）：20世纪60年代末Weinberg等在哺乳动物中发现第一个snoRNA U3。snoRNA是一类小分子非编码RNA，多富集于核仁，代谢稳定。典型snoRNA特征包括：分子大小60~400 nt；具有类似核仁提取物的性质（抗盐性）；需要与特定蛋白质结合形成核糖核蛋白体（snoRNP），并以此形式存在和行使功能；分子具有多种与蛋白质相互作用的保守序列元件。其次介绍细胞核小分子RNA（small nuclear RNA, snRNA）：它是真核生物转录后加工过程中RNA剪接体（spliceosome）的主要成分，哺乳动物中长度100~300个核苷酸。snRNA一直存在于细胞核中，与核内蛋白质共同组成RNA剪接体，在RNA转录后加工中起重要作用。snRNA和许多蛋白质结合形成小核核糖核蛋白（small nuclear ribonucleoproteins, snRNP），参与信使RNA前体（pre-mRNA）的剪接，使后者成为成熟mRNA。snRNA共分为7类，因含U丰富，编号为U1~U7。snRNA只存在于细胞核中。", "page": 138, "level": "掌握", "img": "assets/img/ch07/p138.jpg", "anim": null, "fig": null, "points": ["ncRNA可根据来源、性质和功能不同采用不同分类方法", "按细胞内分布分类，首先介绍核仁小RNA（snoRNA）", "20世纪60年代末Weinberg等发现第一个snoRNA U3", "snoRNA多富集于核仁，代谢稳定", "⚠️ 考点/易错点：考点：snoRNA多富集于核仁、代谢稳定，典型特征为60~400 nt、抗盐性、需与特定蛋白结合；第一个被发现的是U3。"], "code": null, "lang": null, "check": {"q": "关于snoRNA的特征，下列说法正确的是？", "o": ["A. 第一个snoRNA U3于20世纪60年代末在哺乳动物中被发现", "B. snoRNA主要富集于细胞质", "C. snoRNA分子大小通常为20~60 nt", "D. snoRNA不需要与蛋白质结合即可行使功能"], "a": "A", "e": "20世纪60年代末Weinberg等在哺乳动物中发现第一个snoRNA U3；snoRNA多富集于核仁，分子大小60~400 nt，需要与特定蛋白质结合形成snoRNP并以此形式存在和行使功能。"}, "cards": [{"front": "第一个被发现的snoRNA是什么？", "back": "U3。", "mnemonic": "U3开山", "useImg": false}]}, {"i": 5, "sec": "第一节 非编码RNA概述", "title": "人类非编码RNA种类表", "notes": "本页以表7-2列出人类非编码RNA种类（Gibb et al., 2001）。短链非编码RNA包括：microRNAs（miRNAs）、piwi interacting RNAs（piRNAs）、tiny transcription initiation RNAs（tiRNAs）、small interfering RNAs（siRNAs）、promoter-associated short RNAs（PASRs）、termini-associated short RNAs（TASRs）、antisense termini associated RNAs（aTASRs）、small nucleolar RNAs（snoRNAs）、transcription start site antisense RNAs（TSSa-RNAs）、small nuclear RNAs（snRNAs）、retrotransposon-derived RNAs（RE-RNAs）、3'UTR-derived RNA（UaRNAs）、x-ncRNA（x-ncRNAs）、human Y RNA（hYRNAs）、unusually small RNAs（usRNAs）、small NF90-associated RNAs（snaRNAs）、vault RNAs（vtRNAs）。长链非编码RNA包括：long or large intergenic ncRNAs（lincRNAs）、transcribed ultraconserved regions（T-UCRs）、pseudogenes、GAA-repeat containing RNAs（GRC-RNAs）、long intronic ncRNA、antisense RNAs（aRNAs）、promoter-associated RNAs等。该表说明ncRNA种类繁多，分类维度包括长度、来源、基因组位置和功能机制。学习时应能区分短链与长链ncRNA的典型代表，并理解同一ncRNA可能按不同标准归入不同类别。", "page": 139, "level": "掌握", "img": "assets/img/ch07/p139.jpg", "anim": null, "fig": "表7-2列出人类非编码RNA种类，可查看各类ncRNA的名称和特征。", "points": ["人类非编码RNA种类以表7-2列出（Gibb et al., 2001）", "短链非编码RNA包括：microRNAs、piwi interacting RNAs、tiny transcription initiation RNAs、small interfering RNAs、promoter-associated RNAs等", "⚠️ 考点/易错点：易混点：注意区分各类短链ncRNA缩写，如miRNA、piRNA、siRNA、tiRNA、PASR等，考试常考名称与全称对应。"], "code": null, "lang": null, "check": {"q": "根据表7-2，下列哪项属于短链非编码RNA？", "o": ["A. rRNA", "B. piRNAs", "C. lncRNA", "D. mRNA"], "a": "B", "e": "表7-2中短链非编码RNA包括miRNAs、piRNAs、tiRNAs、siRNAs、PASRs等；rRNA和lncRNA不属于短链非编码RNA类别。"}, "cards": [{"front": "短链非编码RNA包括哪些？", "back": "miRNAs、piRNAs、tiRNAs、siRNAs、promoter-associated RNAs等。", "mnemonic": "mi pi ti si  promoter", "useImg": false}]}, {"i": 6, "sec": "第三节 microRNA", "title": "非编码RNA的分类与snoRNA功能", "notes": "本页主要介绍非编码RNA（ncRNA）的功能分类，并重点阐述兼具看家与调节功能的snoRNA。首先，看家ncRNA表达水平受环境变化影响不明显，具有对细胞存活至关重要的功能，如snRNA、SRP RNA等。其次，调节或调控ncRNA可分为转录调控子、RNA分布调控因子、转录后调控因子、蛋白质功能调节因子等，一般在组织发育或细胞分化的特定阶段表达，或响应外界环境应激，随后调控一系列生物过程。第三类为兼具看家功能和调节功能的ncRNA，主要是核仁小分子RNA（snoRNA），广泛分布于真核生物细胞核仁，具有保守结构元件。snoRNA主要修饰rRNA、tRNA和snRNA，近期研究表明snoRNA可形成sdaRNA，一些sdRNA类似于miRNA，与Argonaute蛋白相关，影响翻译过程；另一些较长片段与hnRNP形成复合物并影响基因表达，显示snoRNA既具有看家RNA稳定表达特性，又具有调节RNA的调节作用。snoRNA依据结构单元可分为三大类：box C/D snoRNA、box H/ACA snoRNA和MRP RNA。其中box C/D和box H/ACA是已知主要类型，以碱基配对方式分别指导核糖体RNA的甲基化和假尿嘧啶化修饰。研究发现，snoRNA除在核糖体RNA生物合成中发挥作用外，还能指导snRNA、tRNA和mRNA的转录后修饰。此外，还有相当数量的snoRNA功能不明，被称为孤儿snoRNA（orphan snoRNA）。", "page": 140, "level": "掌握", "img": "assets/img/ch07/p140.jpg", "anim": null, "fig": null, "points": ["看家ncRNA表达水平受环境变化影响不明显，具有对细胞存活至关重要的功能，如snRNA、SRP RNA等", "调节或调控ncRNA可分为转录调控子、RNA分布调控因子、转录后调控因子、蛋白质功能调节因子等", "调节ncRNA一般在组织发育或细胞分化的特定阶段表达，或响应外界环境", "snoRNA兼具看家与调节功能", "⚠️ 考点/易错点：考点：ncRNA按功能分为看家ncRNA、调节ncRNA及兼具两者功能的ncRNA；snoRNA属于兼具看家与调节功能的典型。"], "code": null, "lang": null, "check": {"q": "关于非编码RNA的功能分类，下列说法正确的是？", "o": ["A. 看家ncRNA表达水平受环境变化影响明显", "B. 调节或调控ncRNA一般在组织发育或细胞分化的特定阶段表达", "C. snoRNA只具有看家功能，不具有调节功能", "D. snRNA属于调节或调控ncRNA"], "a": "B", "e": "看家ncRNA表达水平受环境变化影响不明显，如snRNA、SRP RNA等；调节或调控ncRNA一般在组织发育或细胞分化的特定阶段表达，或响应外界环境应激；snoRNA兼具看家功能和调节功能。"}, "cards": [{"front": "看家ncRNA的特点是什么？", "back": "表达水平受环境变化影响不明显，具有对细胞存活至关重要的功能。", "mnemonic": "看家不变，保命要紧", "useImg": false}]}, {"i": 7, "sec": "第三节 microRNA", "title": "miRNA的加工与RISC组装", "notes": "本页以图7-3展示动物和植物miRNA生物合成途径的异同。动物miRNA基因转录生成miRNA初始转录物（pri-miRNA），在细胞核内由Drosha及其辅因子DGCR8/Pasha加工成miRNA前体（pre-miRNA），随后由Exportin-5-RanGTP运输至细胞质。在细胞质中，Dicer蛋白与TRBP或PACT蛋白协同作用，将pre-miRNA加工为成熟miRNA，并加载到Argonaute（AGO1-4）蛋白，生成效应物RNA诱导的沉默复合体（RISC）。植物miRNA合成有所不同：植物中未发现Drosha及其辅因子DGCR8/Pasha的同系物，表明植物细胞中没有依赖于Drosha的加工过程。基因研究显示，Dicer-like 1（DCL-1）专一负责MIRNA的加工。Exportin-5的同系物HASTY（HST）介导miRNA从细胞核到细胞质。miRNA在细胞核或细胞质中加载Argonaute家族蛋白质（AGO）。图中还显示miRNA:miRNA*二聚体解旋后，成熟miRNA加载至AGO蛋白形成RISC。该页强调动物与植物miRNA加工途径的关键差异，是理解miRNA功能机制的基础。", "page": 141, "level": "掌握", "img": "assets/img/ch07/p141.jpg", "anim": null, "fig": "图7-3展示动物和植物miRNA生物合成途径，可对比两者在加工酶和运输机制上的异同。", "points": ["动物miRNA基因转录生成pri-miRNA，在细胞核内由Drosha及其辅因子DGCR8/Pasha加工成pre-miRNA", "pre-miRNA由Exportin-5-RanGTP运输至细胞质", "在细胞质中，Dicer蛋白与TRBP或PACT蛋白协同作用，将pre-miRNA加工成成熟miRNA", "图7-3展示动物和植物miRNA生物合成途径的异同", "⚠️ 考点/易错点：易混点：动物miRNA加工需Drosha/DGCR8（核内）和Dicer/TRBP或PACT（胞质），植物miRNA加工机制不同；成熟miRNA加载到AGO蛋白形成RISC。"], "code": null, "lang": null, "check": {"q": "关于动物miRNA的加工与RISC组装，下列说法正确的是？", "o": ["A. pri-miRNA在细胞质中由Drosha加工成pre-miRNA", "B. pre-miRNA由Exportin-5-RanGTP运输至细胞质", "C. Dicer蛋白在细胞核中将pre-miRNA加工为成熟miRNA", "D. 成熟miRNA加载到Drosha蛋白生成效应复合物"], "a": "B", "e": "动物miRNA基因转录生成pri-miRNA，在细胞核内由Drosha及其辅因子DGCR8/Pasha加工成pre-miRNA，随后由Exportin-5-RanGTP运输至细胞质；在细胞质中Dicer与TRBP或PACT协同将pre-miRNA加工为成熟miRNA，并加载到Argonaute（AGO1-4）蛋白生成效应复合物。"}, "cards": [{"front": "动物miRNA在细胞核内由什么酶加工？", "back": "Drosha及其辅因子DGCR8/Pasha。", "mnemonic": "核内Drosha，辅因子DGCR8", "useImg": false}]}, {"i": 8, "sec": "第三节 microRNA", "title": "miRNA序列信息获取与miRBase数据库", "notes": "本页介绍miRNA生物信息学分析策略的第一步：获取microRNA的序列信息。当前最常用的miRNA权威数据库是miRBase（http://www.mirbase.org/），该数据库提供miRNA注册、序列查询、基因组定位、相关文献查询和靶基因预测等功能。目前已更新到21.0版，涵盖223个物种，包含28,645条miRNA发夹前体，35,828条成熟miRNA。图7-4展示miRBase网站主页，页面显示数据库提供的服务：可通过名称、关键词、参考文献和注释检索；所有序列和注释数据均可下载；miRBase Registry为miRNA基因发现者提供在发表结果前获取新miRNA基因唯一名称的服务。此外，页面还提示已发布4个新的人类基因组组装版本GRCh38，并重新映射了人类数据。该页还提到microRNA新基因的预测和鉴定，指出生物信息学预测利用miRNA在不同物种间的保守性、miRNA前体等特征。掌握miRBase的使用是进行miRNA研究的基础，包括查询已知miRNA、下载序列、提交新miRNA等。", "page": 142, "level": "掌握", "img": "assets/img/ch07/p142.jpg", "anim": null, "fig": null, "points": ["miRBase是最常用的miRNA权威数据库（http://www.mirbase.org/）", "miRBase提供miRNA注册、序列查询、基因组定位、相关文献查询和靶基因预测等功能", "目前已更新到21.0版，涵盖223个物种，包含28,645条miRNA发夹前体，35,828条成熟miRNA", "⚠️ 考点/易错点：miRBase是最权威的miRNA数据库，需记住其功能（注册、序列查询、基因组定位、靶基因预测等）及版本数据（21.0版、223物种、28,645条前体、35,828条成熟miRNA）。"], "code": null, "lang": null, "check": {"q": "关于miRBase数据库，下列说法正确的是？", "o": ["A. miRBase只提供miRNA序列查询，不提供靶基因预测功能", "B. miRBase目前已更新到21.0版，涵盖223个物种", "C. miRBase只包含成熟miRNA，不包含发夹前体", "D. miRBase不提供miRNA基因组定位信息"], "a": "B", "e": "miRBase提供miRNA注册、序列查询、基因组定位、相关文献查询和靶基因预测等功能；目前已更新到21.0版，涵盖223个物种，包含28,645条miRNA发夹前体和35,828条成熟miRNA。"}, "cards": [{"front": "最常用的miRNA权威数据库是什么？", "back": "miRBase。", "mnemonic": "miRBase，miRNA大本营", "useImg": false}]}, {"i": 9, "sec": "第三节 microRNA", "title": "基于降解组与miRNA前体加工信号的miRNA挖掘流程", "notes": "本页展示利用降解组数据集和miRNA前体加工信号挖掘miRNA新基因的生物信息学流程。首先，对降解组数据集进行预处理和归一化（RPM标准化），匹配到转录物并保留精确匹配的序列，分析降解组信号在转录物范围内的分布。基本识别规则包括：对于一个数据集，“切割位点平均读数”应是“周围平均读数”的5倍甚至更多；在切割位点有最高读数的标记应映射在某个转录物种前12个最大量标记之间；切割位点不应出现在转录物中开始或最后的1个核苷酸中。然后计算潜在切割位点，并利用21个核苷酸“诱饵”序列收集诱饵序列，匹配“诱饵”序列到AGO1富集的sRNA数据集，获得第一个5000反向互补结果，保留读数≥1 RPM的19-24个核苷酸的sRNAs，得到一组潜在mRNA调控者。用默认参数进行miRNA预测，去除没有靶基因预测的sRNAs，去除有预测结合位点而没有潜在切割位点的sRNAs，进行多次筛选。将2个核苷酸悬挂的sRNA归为一类，在一类中只有最大丰度sRNA包含在后续分析中，把包含一个或多个错配且位于长链区域的sRNA作为一个独立子群进一步分析。最后将筛选后的sRNAs Blast到基因组上，对于没有精确匹配基因座的sRNA，保留不超过两个错配的相似基因座，识别基因座，收集1400个核苷酸基因序列，进行聚类。该流程是miRNA Digger软件的核心算法基础。", "page": 143, "level": "理解", "img": "assets/img/ch07/p143.jpg", "anim": null, "fig": null, "points": ["利用降解组数据集和miRNA前体加工信号挖掘miRNA新基因", "对降解组数据集进行预处理和归一化（RPM标准化），匹配到转录物并保留精确匹配的序列", "基本识别规则：切割位点平均读数应是周围平均读数的5倍甚至更多", "在切割位点有最高读数的标记应映射在某个转录物种前12个最大读数的位置", "⚠️ 考点/易错点：降解组挖掘miRNA的核心识别规则：切割位点平均读数应为周围平均读数的5倍以上，且切割位点不能位于转录物起始或末尾的1个核苷酸内。"], "code": null, "lang": null, "check": {"q": "关于基于降解组与miRNA前体加工信号的miRNA挖掘流程，下列说法正确的是？", "o": ["A. 降解组数据集预处理时使用TPM标准化", "B. 基本识别规则要求切割位点平均读数是周围平均读数的5倍甚至更多", "C. 切割位点应出现在转录物中开始或最后的1个核苷酸中", "D. 在切割位点有最高读数的标记应映射在某个转录物种前12个最大量标记之外"], "a": "B", "e": "降解组数据集预处理和归一化使用RPM标准化；基本识别规则包括切割位点平均读数应是周围平均读数的5倍甚至更多，在切割位点有最高读数的标记应映射在某个转录物种前12个最大量标记之间，切割位点不应出现在转录物中开始或最后的1个核苷酸中。"}, "cards": [{"front": "降解组挖掘miRNA的基本识别规则中，切割位点平均读数应是周围平均读数的多少倍？", "back": "5倍甚至更多。", "mnemonic": "五倍起步", "useImg": false}]}, {"i": 10, "sec": "第三节 microRNA", "title": "miRNA Digger软件与miRNA靶基因预测", "notes": "本页首先说明动物miRNA对靶基因主要通过翻译抑制而不是切割进行调控，降解组无法发现靶基因上的切割位点，因此该逆向挖掘技术只适合植物miRNA基因的大规模挖掘。但研究发现，miRNA前体上由Dicer（动物）/DCL（植物）介导产生的切割信号可被降解组测序探测到，且切割信号的位置与miRNA(5p)/miRNA*(-3p)的边界高度相关，可作为寻找miRNA新基因的标记。利用降解组对全基因组进行切割位点扫描，从基因组上截取包含切割位点的候选miRNA前体，通过发卡二级结构筛选后将sRNA高通量测序数据匹配到前体上，利用切割位点与miRNA(-5p)/miRNA*(-3p)边界的高度相关性，可获得候选miRNA。基于这一思路，建立了大规模挖掘miRNA新基因的新算法（Lan et al., 2016），并编写了免费共享软件miRNA Digger（http://www.bioinfolab.cn/miRNA_Digger/index.html）。图7-6展示该软件界面，包含Help、Data_Process、miRNA等模块。与前期建立的miRNA逆向挖掘技术相比，该方法不仅可用于植物，也能用于动物miRNA新基因的大规模挖掘。随后介绍miRNA靶基因的预测和鉴定：RISC复合体在miRNA指导下识别靶基因，如果miRNA与靶基因几乎完全互补，则切割靶基因；如果互补程度较低，则抑制靶基因翻译。由于miRNA与其靶基因并非完全匹配，给确定miRNA靶基因带来一定难度。", "page": 144, "level": "掌握", "img": "assets/img/ch07/p144.jpg", "anim": null, "fig": null, "points": ["动物miRNA对靶基因主要通过翻译抑制而不是切割进行调控，降解组无法发现靶基因上的切割位点", "逆向挖掘技术只适合植物miRNA基因的大规模挖掘", "miRNA前体上由Dicer（动物）/DCL（植物）介导产生的切割信号可被降解组测序探测到", "切割信号的位置与miRNA(5p)/miRNA*(-3p)的边界高度相关，可作为寻找miRNA基因的依据", "miRNA Digger软件用于miRNA挖掘", "⚠️ 考点/易错点：易错点：动物miRNA主要靠翻译抑制而非切割调控靶基因，故该降解组逆向挖掘技术只适合植物miRNA基因的大规模挖掘；miRNA前体上Dicer/DCL介导的切割信号位置与miRNA(5p)/miRNA*(-3p)边界高度相关。"], "code": null, "lang": null, "check": {"q": "关于miRNA Digger软件与miRNA靶基因预测，下列说法正确的是？", "o": ["A. 动物miRNA主要通过切割靶基因进行调控，降解组可发现靶基因上的切割位点", "B. 该逆向挖掘技术只适合植物miRNA基因的大规模挖掘", "C. miRNA前体上由Dicer/DCL介导产生的切割信号不能被降解组测序探测到", "D. 切割信号的位置与miRNA(5p)/miRNA*(-3p)的边界无关"], "a": "B", "e": "动物miRNA对靶基因主要通过翻译抑制而不是切割进行调控，降解组无法发现靶基因上的切割位点，因此该逆向挖掘技术只适合植物miRNA基因的大规模挖掘；miRNA前体上由Dicer（动物）/DCL（植物）介导产生的切割信号可被降解组测序探测到，且切割信号的位置与miRNA(5p)/miRNA*(-3p)的边界高度相关。"}, "cards": [{"front": "为什么降解组逆向挖掘技术只适合植物miRNA基因的大规模挖掘？", "back": "动物miRNA对靶基因主要通过翻译抑制而不是切割进行调控，降解组无法发现靶基因上的切割位点。", "mnemonic": "动物抑制，植物切割", "useImg": false}]}, {"i": 11, "sec": "第三节 microRNA", "title": "psRNATarget靶基因预测网站及实例", "notes": "本页以具体miRNA（UUCGCUUGCAGAGAGAAAUCAC）的靶基因鉴定为例，介绍psRNATarget靶基因预测网站的使用。图7-7展示psRNATarget网站主页，该网站提供Analysis、About、Citation、Analysis、Download、Location等功能模块。分析页面允许用户提交小RNA序列或预加载转录本，支持上传FASTA格式的小RNA序列，或直接粘贴序列，无效小RNA将在分析中被忽略。用户可选择预加载的转录本库或自定义靶基因序列。图7-8展示预测结果：用psRNATarget预测到该miRNA有5个靶基因，记录靶基因名称和结合位置信息。结果页面显示Batch Download、Prev Page、Next Page，共1页5条记录。表格中包含miRNA序列、靶基因名称、结合位置、期望值等信息。该页通过实例演示了如何利用psRNATarget进行miRNA靶基因预测，是miRNA功能研究的重要步骤。掌握该工具的使用有助于理解miRNA与靶基因的相互作用机制。", "page": 145, "level": "掌握", "img": "assets/img/ch07/p145.jpg", "anim": null, "fig": "图7-7展示psRNATarget网站主页，可查看各功能模块和输入界面。", "points": ["psRNATarget是靶基因预测网站，提供Analysis、About、Citation、Download、Location等功能模块", "分析页面允许用户提交小RNA序列或预加载转录本，支持上传FASTA文件", "以具体miRNA（UUCGCUUGCAGAGAGAAAUCAC）的靶基因鉴定为例", "图7-7展示psRNATarget网站主页", "⚠️ 考点/易错点：psRNATarget是靶基因预测网站，需掌握其功能模块（Analysis、Download等）及提交方式（FASTA格式或粘贴序列），无效小RNA会被忽略。"], "code": null, "lang": null, "check": {"q": "关于psRNATarget靶基因预测网站，下列说法正确的是？", "o": ["A. psRNATarget只支持上传FASTA格式的小RNA序列，不支持直接粘贴序列", "B. 无效小RNA将在分析中被忽略", "C. psRNATarget不提供Download功能模块", "D. psRNATarget只能分析预加载转录本，不能提交小RNA序列"], "a": "B", "e": "psRNATarget分析页面允许用户提交小RNA序列或预加载转录本，支持上传FASTA格式的小RNA序列或直接粘贴序列，无效小RNA将在分析中被忽略；网站提供Analysis、About、Citation、Download、Location等功能模块。"}, "cards": [{"front": "psRNATarget网站的主要功能是什么？", "back": "miRNA靶基因预测。", "mnemonic": "psRNA，靶基因预测", "useImg": false}]}, {"i": 12, "sec": "第三节 microRNA", "title": "降解组测序鉴定miRNA靶基因及切割位点", "notes": "本页展示利用降解组测序（degradome sequencing）验证miRNA靶基因的实例。图7-9为拟南芥AT2G27400.1的降解组匹配结果表，列出各降解片段序列、匹配位置及测序计数。表中‘Perfect_match’表示降解片段与靶基因完全匹配，‘Degradome_sequence_count’为支持该切割位点的读段数，‘5’_match_position’为切割位点位置。若miRNA结合位点位于降解片段中间附近，则该靶基因预测较可靠；若偏离结合位点中间较远，则可能为假阳性。图7-10为切割位点分布图，横轴为靶基因位置，纵轴为降解片段计数，峰值379处提示主要切割位点。通过降解组数据可实验性验证miRNA靶标，弥补纯计算预测假阳性高的不足。", "page": 146, "level": "理解", "img": "assets/img/ch07/p146.jpg", "anim": null, "fig": "图7-9为拟南芥AT2G27400.1的降解组匹配结果表，可查看各降解片段序列、匹配位置及测序计数。", "points": ["利用降解组测序验证miRNA靶基因", "图7-9为拟南芥AT2G27400.1的降解组匹配结果表", "表中‘Perfect_match’表示降解片段与靶基因完全匹配", "‘Degradome_sequence_count’为支持该切割位点的读段数", "‘5’_match_position’表示降解片段5′端匹配位置", "⚠️ 考点/易错点：降解组验证靶基因时，若miRNA结合位点位于降解片段中间附近，则该靶基因可被判定为miRNA的靶标；需区分Perfect_match、Degradome_sequence_count、5'_match_position等字段含义。"], "code": null, "lang": null, "check": {"q": "关于利用降解组测序鉴定miRNA靶基因及切割位点，下列说法正确的是？", "o": ["A. 表中‘Perfect_match’表示降解片段与靶基因不完全匹配", "B. ‘Degradome_sequence_count’为支持该切割位点的读段数", "C. ‘5’_match_position’为切割位点位置，与miRNA结合位点无关", "D. 若miRNA结合位点位于降解片段中间附近，则该靶基因不太可能被切割"], "a": "B", "e": "‘Perfect_match’表示降解片段与靶基因完全匹配；‘Degradome_sequence_count’为支持该切割位点的读段数；‘5’_match_position’为切割位点位置；若miRNA结合位点位于降解片段中间附近，则该靶基因可能被切割。"}, "cards": [{"front": "降解组测序中‘Perfect_match’表示什么？", "back": "降解片段与靶基因完全匹配。", "mnemonic": "完美匹配", "useImg": false}]}, {"i": 13, "sec": "第三节 microRNA", "title": "miRNA靶标预测软件与circRNA概述及生物合成", "notes": "本页首先列出miRNA靶标预测软件starBase，其整合CLIP-Seq（如HITS-CLIP）和mRNA降解组数据，构建多个预测软件的交集，降低假阳性。随后进入第四节circRNA。circRNA是一类以共价键形成闭环结构的内源性RNA，无5′端、3′端及polyA尾，因此经典polyA富集方法难以检测，长期被忽视。高通量测序和生物信息学发展揭示其在真核细胞中广泛多样存在，并参与疾病发生。circRNA通常由反向剪接（back splicing）产生。图7-11示意四种形成途径：套索驱动、内含子配对驱动、外显子跳跃套索驱动及蛋白因子结合驱动。本页为circRNA生物合成机制的总览。", "page": 147, "level": "掌握", "img": "assets/img/ch07/p147.jpg", "anim": null, "fig": null, "points": ["starBase整合CLIP-Seq和mRNA降解组数据，构建多个预测软件的交集，降低假阳性", "circRNA是一类以共价键形成闭环结构的内源性RNA，无5′端、3′端及polyA尾", "经典polyA富集方法难以检测circRNA，长期被忽视", "高通量测序和生物信息学发展揭示其在真核生物中广泛存在", "⚠️ 考点/易错点：starBase整合CLIP-Seq和降解组数据、取多软件交集以降低假阳性；circRNA因闭环、无5′/3′端及polyA尾，经典polyA富集方法难以检测，通常由反向剪接形成。"], "code": null, "lang": null, "check": {"q": "关于miRNA靶标预测软件与circRNA概述，下列说法正确的是？", "o": ["A. starBase整合CLIP-Seq和mRNA降解组数据，构建多个预测软件的交集以降低假阳性", "B. circRNA具有5′端、3′端及polyA尾，易于用经典polyA富集方法检测", "C. circRNA是一类以非共价键形成开环结构的内源性RNA", "D. circRNA通常由正向剪接产生"], "a": "A", "e": "starBase整合CLIP-Seq（如HITS-CLIP）和mRNA降解组数据，构建多个预测软件的交集，降低假阳性；circRNA以共价键形成闭环结构，无5′端、3′端及polyA尾，经典polyA富集方法难以检测，通常由反向剪接产生。"}, "cards": [{"front": "circRNA的结构特点是什么？", "back": "以共价键形成闭环结构，无5′端、3′端及polyA尾。", "mnemonic": "闭环无尾", "useImg": false}]}, {"i": 14, "sec": "第三节 microRNA", "title": "circRNA生物合成途径与特性", "notes": "本页详述circRNA四种生物合成途径。1）剪接体依赖途径：snRNP装配后，下游外显子5′供体位点与上游3′受体位点结合，促进环化。2）内含子配对驱动：反向互补motif促进环化，5′剪接位点附近为7nt GU富集片段，分支位点附近为11nt C富集片段，供体-受体空间靠近推动成环。3）套索驱动：外显子跳跃剪接产生套索副产物，被跳过区域经套索剪接形成外显子环状RNA；侧翼内含子中Alu元件重复和反向互补序列富集是该途径特征。4）蛋白因子结合：RBP结合内含子靶序列，使供体-受体靠近促进环化，也可妨碍线性剪接或抑制环化。circRNA特性包括无polyA尾、闭环结构、广泛存在等，其发现解释了基因序列‘混乱’现象。", "page": 148, "level": "掌握", "img": "assets/img/ch07/p148.jpg", "anim": null, "fig": null, "points": ["circRNA四种生物合成途径：剪接体依赖途径、内含子配对驱动、套索驱动、外显子跳跃剪接产生套索副产物", "剪接体依赖途径：snRNP装配后，下游外显子5′供体位点与上游3′受体位点结合，促进环化", "内含子配对驱动：反向互补motif促进环化，5′剪接位点附近为7nt GU富集片段，分支位点附近为11nt C富集片段", "套索驱动：外显子跳跃剪接产生套索副产物，被跳过区域经套索剪接形成外显子环状RNA", "⚠️ 考点/易错点：四种circRNA生物合成途径易混：剪接体依赖途径、内含子配对驱动（7nt GU富集、11nt C富集）、套索驱动（外显子跳跃、Alu元件富集）、蛋白因子驱动，需对应各自特征。"], "code": null, "lang": null, "check": {"q": "关于circRNA生物合成途径与特性，下列说法正确的是？", "o": ["A. 剪接体依赖途径中，下游外显子5′供体位点与上游3′受体位点结合促进环化", "B. 内含子配对驱动途径中，5′剪接位点附近为11nt C富集片段", "C. 套索驱动途径中，侧翼内含子中Alu元件重复和反向互补序列贫乏是该途径特征", "D. 蛋白因子驱动途径与RNA结合蛋白无关"], "a": "A", "e": "剪接体依赖途径中，snRNP装配后，下游外显子5′供体位点与上游3′受体位点结合，促进环化；内含子配对驱动中5′剪接位点附近为7nt GU富集片段，分支位点附近为11nt C富集片段；套索驱动途径中侧翼内含子中Alu元件重复和反向互补序列富集；蛋白因子驱动途径与RNA结合蛋白相关。"}, "cards": [{"front": "circRNA的四种生物合成途径是什么？", "back": "剪接体依赖途径、内含子配对驱动、套索驱动、外显子跳跃剪接产生套索副产物。", "mnemonic": "剪配套跳", "useImg": false}]}, {"i": 15, "sec": "第三节 microRNA", "title": "circRNA分类与主要生物学功能", "notes": "本页介绍circRNA分类：外显子环状RNA（ecircRNA）、内含子环状RNA（ciRNA）、外显子-内含子环状RNA（EIciRNA）、反义链来源及基因间区来源环状RNA。ecircRNA主要定位细胞质，参与转录后调控；ciRNA和EIciRNA定位细胞核，调节亲本线性mRNA转录。图7-12展示circRNA五种功能：1）作为竞争性内源RNA（ceRNA）海绵吸附miRNA，如CDR1来源的ciRS-7吸附miR-7，降低其活性，间接上调miR-7靶基因；2）调控亲本基因表达；3）翻译蛋白质；4）产生假基因；5）影响选择性剪接。circRNA在疾病发生发展中起重要作用，可作为潜在治疗生物标志物。", "page": 149, "level": "掌握", "img": "assets/img/ch07/p149.jpg", "anim": null, "fig": "图7-12展示circRNA五种功能，可查看每种功能的示意图和说明。", "points": ["circRNA分类：外显子环状RNA（ecircRNA）、内含子环状RNA（ciRNA）、外显子-内含子环状RNA（EIciRNA）、反义链来源及基因间区来源环状RNA", "ecircRNA主要定位细胞质，参与转录后调控", "ciRNA和EIciRNA定位细胞核，调节亲本线性mRNA转录", "图7-12展示circRNA五种功能：作为ceRNA、调控转录、调控剪接、翻译蛋白质、作为生物标志物", "⚠️ 考点/易错点：circRNA分类（ecircRNA、ciRNA、EIciRNA等）与定位/功能易混：ecircRNA主要在细胞质参与转录后调控，ciRNA和EIciRNA在细胞核调节亲本线性mRNA转录；ciRS-7吸附miR-7是ceRNA海绵的经典例子。"], "code": null, "lang": null, "check": {"q": "关于circRNA分类与主要生物学功能，下列说法正确的是？", "o": ["A. ecircRNA主要定位细胞核，调节亲本线性mRNA转录", "B. ciRNA和EIciRNA定位细胞质，参与转录后调控", "C. ciRS-7可吸附miR-7，降低其活性", "D. circRNA不能作为竞争性内源RNA（ceRNA）海绵吸附miRNA"], "a": "C", "e": "ecircRNA主要定位细胞质，参与转录后调控；ciRNA和EIciRNA定位细胞核，调节亲本线性mRNA转录；circRNA可作为ceRNA海绵吸附miRNA，如CDR1来源的ciRS-7吸附miR-7，降低其活性。"}, "cards": [{"front": "circRNA按来源分为哪几类？", "back": "外显子环状RNA（ecircRNA）、内含子环状RNA（ciRNA）、外显子-内含子环状RNA（EIciRNA）、反义链来源及基因间区来源环状RNA。", "mnemonic": "外内内外反间", "useImg": false}]}, {"i": 16, "sec": "第三节 microRNA", "title": "circRNA在线数据库与分析软件及其他小分子RNA", "notes": "本页列举circRNA常用数据库和软件：1）deepBase v2.0，含约15万circRNA基因，覆盖人、鼠、果蝇、线虫等，构建全面表达图谱；2）circBase，收集整合已发布circRNA数据；3）CircNet，提供新circRNA鉴定、circRNA-miRNA-mRNA互作网络、亚型表达水平、基因组注释和序列；4）CircPro，整合Ribo-seq和RNA-seq预测circRNA及其编码潜能；5）miARma-Seq，综合分析mRNA、miRNA和circRNA，可区分表达量、预测靶基因和功能分析。随后进入第五节其他小分子RNA，定义小分子RNA为20~40个核苷酸的非编码RNA，广泛存在于真核生物，在转录或转录后调节基因表达。", "page": 150, "level": "理解", "img": "assets/img/ch07/p150.jpg", "anim": null, "fig": null, "points": ["deepBase v2.0含约15万circRNA基因，覆盖人、鼠、果蝇、线虫等，构建全面表达图谱", "circBase收集整合已发布circRNA数据", "CircNet提供新circRNA鉴定、circRNA-miRNA-mRNA互作网络、亚型表达水平、基因组注释和序列", "CircPro整合Ribo-Seq数据用于circRNA编码潜能预测", "⚠️ 考点/易错点：circRNA数据库功能易混：deepBase v2.0侧重跨物种表达图谱，circBase侧重数据整合，CircNet侧重互作网络，CircPro侧重编码潜能预测，注意各库核心功能对应。"], "code": null, "lang": null, "check": {"q": "关于circRNA在线数据库与分析软件，下列说法正确的是？", "o": ["A. deepBase v2.0只包含人类circRNA数据", "B. circBase收集整合已发布circRNA数据", "C. CircNet不提供circRNA-miRNA-mRNA互作网络", "D. CircPro不能预测circRNA编码潜能"], "a": "B", "e": "deepBase v2.0含约15万circRNA基因，覆盖人、鼠、果蝇、线虫等；circBase收集整合已发布circRNA数据；CircNet提供新circRNA鉴定、circRNA-miRNA-mRNA互作网络等；CircPro整合Ribo-seq和RNA-seq预测circRNA及其编码潜能。"}, "cards": [{"front": "哪个数据库提供circRNA-miRNA-mRNA互作网络？", "back": "CircNet。", "mnemonic": "CircNet，网络互作", "useImg": false}]}, {"i": 17, "sec": "第三节 microRNA", "title": "siRNA与RNA干扰机制", "notes": "本页详述siRNA与RNA干扰（RNAi）机制。RNAi是实验室强大工具，利用同源双链RNA诱导序列特异的目标基因沉默。siRNA在RNA沉默通道中起中心作用，是RNAi途径的中间产物和效应必需因子。siRNA形成主要由Dicer和Rde-1调控：外源dsRNA被Rde-1识别，引导dsRNA与Dicer结合形成酶-dsRNA复合体；Dicer作用下，dsRNA正义链被靶mRNA替换并释放，在ATP参与下RISC利用核酸内切酶活性切割靶mRNA与反义链互补区域，形成21~23nt的siRNA。RNAi关键步骤是组装RISC和合成介导特异性反应的siRNA蛋白。siRNA并入RISC后，与靶标基因编码区或UTR完全配对，降解靶标基因。siRNA只降解序列互补的mRNA，通过互补配对沉默相应等位基因，是典型负调控机制，识别靶序列高度特异，降解首先发生在相对于siRNA的中央位置。", "page": 151, "level": "掌握", "img": "assets/img/ch07/p151.jpg", "anim": null, "fig": null, "points": ["RNAi利用同源双链RNA诱导序列特异的目标基因沉默", "siRNA在RNA沉默通道中起中心作用，是RNAi途径的中间产物和效应必需因子", "siRNA形成主要由Dicer和Rde-1调控", "外源dsRNA被Rde-1识别，引导dsRNA与Dicer结合形成酶-dsRNA复合体", "Dicer作用下，dsRNA被切割成siRNA", "⚠️ 考点/易错点：RNAi机制核心：外源dsRNA由Rde-1识别，Dicer切割形成siRNA，RISC利用核酸内切酶活性切割靶mRNA，注意Dicer与RISC的分工及ATP参与。"], "code": null, "lang": null, "check": {"q": "关于siRNA与RNA干扰机制，下列说法正确的是？", "o": ["A. RNAi利用同源双链RNA诱导序列特异的目标基因沉默", "B. siRNA形成主要由Dicer和Drosha调控", "C. 外源dsRNA被Exportin-5识别", "D. RISC利用核酸外切酶活性切割靶mRNA"], "a": "A", "e": "RNAi是实验室强大工具，利用同源双链RNA诱导序列特异的目标基因沉默；siRNA形成主要由Dicer和Rde-1调控；外源dsRNA被Rde-1识别；RISC利用核酸内切酶活性切割靶mRNA。"}, "cards": [{"front": "RNAi中siRNA形成主要由哪些因子调控？", "back": "Dicer和Rde-1。", "mnemonic": "Dicer切，Rde-1识", "useImg": false}]}, {"i": 18, "sec": "第五节 其他小分子RNA", "title": "ta-siRNA生成模型与piRNA概述", "notes": "本页承接ta-siRNA生物合成，重点介绍其生成模型与piRNA基本概念。ta-siRNA（trans-acting siRNA）的生成依赖miRNA或siRNA对TAS基因初级转录本的切割。第一种模型要求激发miRNA长度为22nt，目前绝大多数激发ta-siRNA合成的miRNA或siRNA符合此模型；第二种模型认为不对称的miRNA/miRNA*二聚体也可激发ta-siRNA合成。TAS初级转录本被切割后并不降解，而是在SGS3和RDR6作用下复制形成dsRNA，随后DCL4从miRNA剪切位点开始以21nt为单位进行连续相位切割，产生3'端具有2个悬挂碱基的双链siRNA。双链ta-siRNA中的一条链与AGO蛋白形成复合物，介导其他基因的切割降解。ta-siRNA参与植物生长期转换、环境适应、花叶等侧生器官背腹性发育等重要过程，是miRNA调控机制的重要组成部分。部分蛋白质编码基因也可生成ta-siRNA，且某些ta-siRNA可激发靶基因形成下一级ta-siRNA。piRNA（Piwi-interacting RNA）是与Piwi蛋白相互作用的RNA，在基因组中成簇分布，簇长20~90kb，主要来源于单链。piRNA在人类和小鼠中均有发现，大部分基因簇出现在同一染色体位置。生殖细胞中piRNA富集，Piwi突变导致男性不育，表明piRNA在配子形成中起作用。piRNA生物合成有初级合成和次级合成两个主要途径。", "page": 152, "level": "掌握", "img": "assets/img/ch07/p152.jpg", "anim": null, "fig": null, "points": ["ta-siRNA生成依赖miRNA或siRNA对TAS基因初级转录本的切割", "第一种模型要求激发miRNA长度为22nt，目前绝大多数激发ta-siRNA合成的miRNA或siRNA符合此模型", "第二种模型认为不对称的miRNA/miRNA*二聚体", "piRNA基本概念：与PIWI蛋白相互作用的小RNA", "⚠️ 考点/易错点：ta-siRNA生成两种模型易混：第一种要求激发miRNA长度为22nt（绝大多数符合），第二种为不对称miRNA/miRNA*二聚体；且TAS初级转录本被切割后不降解。"], "code": null, "lang": null, "check": {"q": "关于ta-siRNA生成模型与piRNA概述，下列说法正确的是？", "o": ["A. ta-siRNA生成不依赖miRNA或siRNA对TAS基因初级转录本的切割", "B. 第一种模型要求激发miRNA长度为22nt", "C. 第二种模型认为对称的miRNA/miRNA*二聚体可激发ta-siRNA合成", "D. TAS初级转录本被切割后立即降解"], "a": "B", "e": "ta-siRNA生成依赖miRNA或siRNA对TAS基因初级转录本的切割；第一种模型要求激发miRNA长度为22nt，目前绝大多数激发ta-siRNA合成的miRNA或siRNA符合此模型；第二种模型认为不对称的miRNA/miRNA*二聚体也可激发ta-siRNA合成；TAS初级转录本被切割后并不降解，而是在SGS3等作用下继续加工。"}, "cards": [{"front": "ta-siRNA生成的第一种模型要求激发miRNA长度为多少？", "back": "22nt。", "mnemonic": "22nt激发", "useImg": false}]}, {"i": 19, "sec": "第五节 其他小分子RNA", "title": "piRNA的初级合成与乒乓循环", "notes": "本页详细阐述piRNA的两条生物合成途径。初级合成：在果蝇卵巢中，初级合成路径存在于生殖细胞和周围体细胞，而乒乓循环只存在于生殖细胞。在体细胞初级路径中，PIWI亚家族仅Piwi表达，piRNA前体从piRNA簇转录，如flamenco(flam)基因座的长单链经过多步转录。长初级转录产物进入细胞质被加工成中等长度，详细步骤仍未知。加工需要位于线粒体表面的Zucchini(Zuc)核酸内切酶，常生成5'端为U的前体RNA。转运和成熟步骤可能发生在细胞核周围，形成于线粒体表面的颗粒称为Yb体。前体加工过程中，Minotaur(Mino)和GasZ聚集于线粒体表面发挥作用。在未知的3'-5'核酸外切酶作用下，前体进一步剪切加工成成熟piRNA大小。DmHen1/Pimet甲基转移酶和2'-O-甲基转移酶进一步作用生成成熟Piwi-piRNA复合物或Piwi-piRISC。Piwi-piRNA复合物进入细胞核调节目标基因，无Piwi蛋白的piRNA留在细胞质中。在果蝇生殖系细胞中，初级piRNA也来源于如42AB座双链piRNA，并加载到Aub和Piwi蛋白形成piRISC。次级合成：Aub-piRISC复合体启动细胞质中的乒乓循环，与AGO3一起生成次级piRNA。乒乓循环发生在细胞核周围一个电子致密的称为nuage的非膜结构，Piwi蛋白和许多piRNA产生因子在此聚集。在乒乓路径中，AGO3和Aub以互补方式在剪切活性作用下切开正反转位子转录物，piRNA以前馈方式放大。", "page": 153, "level": "掌握", "img": "assets/img/ch07/p153.jpg", "anim": null, "fig": null, "points": ["piRNA两条生物合成途径：初级合成和乒乓循环", "初级合成路径存在于生殖细胞和周围体细胞，乒乓循环只存在于生殖细胞", "在体细胞初级路径中，PIWI亚家族仅Piwi表达，piRNA前体从piRNA簇转录", "长初级转录产物进入细胞质被加工成中等长度，需要位于线粒体表面的Z", "乒乓循环依赖PIWI蛋白和piRNA的扩增", "⚠️ 考点/易错点：piRNA两条途径的场所差异是易考点：初级合成存在于生殖细胞和周围体细胞，乒乓循环只存在于生殖细胞；Zucchini(Zuc)位于线粒体表面，常生成5'端为U的前体。"], "code": null, "lang": null, "check": {"q": "关于piRNA的初级合成与乒乓循环，下列说法正确的是？", "o": ["A. 乒乓循环存在于生殖细胞和周围体细胞", "B. 初级合成路径只存在于生殖细胞", "C. 在体细胞初级路径中，PIWI亚家族仅Piwi表达", "D. Zucchini(Zuc)核酸内切酶位于细胞核内"], "a": "C", "e": "在果蝇卵巢中，初级合成路径存在于生殖细胞和周围体细胞，而乒乓循环只存在于生殖细胞；在体细胞初级路径中，PIWI亚家族仅Piwi表达；Zucchini(Zuc)核酸内切酶位于线粒体表面。"}, "cards": [{"front": "piRNA的乒乓循环只存在于哪种细胞？", "back": "生殖细胞。", "mnemonic": "乒乓只在生殖", "useImg": false}]}, {"i": 20, "sec": "第五节 其他小分子RNA", "title": "snoRNA与snRNA的特征及功能", "notes": "本页介绍snoRNA和snRNA两类小分子非编码RNA。snoRNA（核仁小分子RNA）是一类小分子非编码RNA，多富集于核仁，代谢稳定。典型snoRNA特征：分子大小60~400nt；具有类似核仁提取物的性质（抗盐性）；需要与特定蛋白质结合形成核糖核蛋白体（snoRNP）并以此形式存在和行使功能；具有多种与蛋白质相互作用的保守序列元件。box C/D snoRNA能形成“发夹-单链-发夹-尾部”状二级结构，其分子两端的boxC、boxD以及末端配对序列能形成保守的“茎-内环-茎”状二级结构，称为“K-turn”结构。大多数box C/D snoRNA和box H/ACA snoRNA分别具有指导rRNA、snRNA和tRNA前体中特定核苷2'-O-核糖甲基化修饰与假尿嘧啶化修饰的功能；少部分snoRNA参与rRNA前体的加工剪切，与rRNA的正确折叠和组装相关。MRP RNA是极为特殊的snoRNA，在数量和功能上均异于其他snoRNA。MRP RNA只有一种分子存在于细胞中，并与9种蛋白质结合形成MRP RNA复合物，参与5.8S rRNA的加工和线粒体DNA的复制；还作为RNase P的RNA成分，参与tRNA的5'端成熟过程。snRNA（小核RNA）是剪接体的主要成分，参与mRNA前体的加工过程。此外还有端粒酶RNA，与染色体末端的复制有关；以及反义RNA等。", "page": 154, "level": "理解", "img": "assets/img/ch07/p154.jpg", "anim": null, "fig": null, "points": ["snoRNA多富集于核仁，代谢稳定，分子大小60~400nt", "snoRNA具有类似核仁提取物的性质（抗盐性）", "snoRNA需要与特定蛋白质结合形成snoRNP并以此形式存在和行使功能", "snoRNA具有多种与蛋白质相互作用的保守序列元件", "box C/D snoRNA和box H/ACA snoRNA是两类主要snoRNA", "⚠️ 考点/易错点：snoRNA特征易考：60~400nt、富集核仁、需与蛋白质结合成snoRNP行使功能；box C/D snoRNA形成“发夹-单链-发夹-尾部”二级结构，两端有boxC、boxD元件。"], "code": null, "lang": null, "check": {"q": "关于snoRNA与snRNA的特征及功能，下列说法正确的是？", "o": ["A. snoRNA分子大小通常为60~400nt", "B. snoRNA不需要与特定蛋白质结合形成snoRNP", "C. box C/D snoRNA能形成“发夹-单链-发夹-尾部”状二级结构", "D. snoRNA主要富集于细胞质"], "a": "A", "e": "snoRNA分子大小60~400nt，多富集于核仁，需要与特定蛋白质结合形成snoRNP并以此形式存在和行使功能；box C/D snoRNA能形成“发夹-单链-发夹-尾部”状二级结构，其分子两端的boxC、boxD等为保守序列元件。"}, "cards": [{"front": "snoRNA的典型特征有哪些？", "back": "分子大小60~400nt；具有抗盐性；需要与特定蛋白质结合形成snoRNP；具有多种保守序列元件。", "mnemonic": "小、抗盐、结合蛋白、保守元件", "useImg": false}]}, {"i": 21, "sec": "第五节 其他小分子RNA", "title": "非编码RNA参考文献列表", "notes": "本页为第七章非编码RNA的参考文献列表，列出了多篇相关研究文献。包括：Iadevaia V和Gerber AP于2015年在Biomolecules上发表的关于RNA结合蛋白和非编码RNA组合控制mRNA命运的文章；Iwasaki YW等2015年在Annual Review of Biochemistry上关于PIWI相互作用RNA生物合成与功能的综述；Jing L等2017年在Molecular Cancer上关于环状RNA重塑RNA世界的文章；Jouannet V和Maizel A 2012年关于反式作用小干扰RNA生物合成、作用模式及在植物发育中作用的专著；Lan Y等2016年在Scientific Reports上关于miRNA Digger——全基因组新miRNA挖掘综合流程的文章；Li X等2017年关于NONCODE数据库的文章。本页为整页参考文献，无具体概念或方法讲解，阅读时注意文献作者、年份、期刊和主题，可用于追溯本章知识点的原始出处和深入阅读。", "page": 155, "level": "了解", "img": "assets/img/ch07/p155.jpg", "anim": null, "fig": null, "points": ["第七章非编码RNA参考文献列表", "包括Iadevaia V和Gerber AP于2015年发表的关于RNA结合蛋白和非编码RNA组合控制mRNA命运的文章", "Iwasaki YW等2015年在Annual Review of Biochemistry上关于PIWI相互作用RNA生物合成与功能的综述", "⚠️ 考点/易错点：本页为参考文献列表，非知识点页；若考则可能涉及PIWI相互作用RNA综述（Iwasaki等2015）或环状RNA综述（Jing等2017）的出处与年份。"], "code": null, "lang": null, "check": {"q": "关于非编码RNA参考文献列表，下列说法正确的是？", "o": ["A. Iadevaia V和Gerber AP于2015年在Biomolecules上发表关于RNA结合蛋白和非编码RNA组合控制mRNA命运的文章", "B. Iwasaki YW等2015年在Nature上发表关于PIWI相互作用RNA的综述", "C. Jing L等2017年在Molecular Cancer上发表关于环状RNA重塑RN的论文", "D. 该参考文献列表只包含2017年发表的文献"], "a": "A", "e": "Iadevaia V和Gerber AP于2015年在Biomolecules上发表了关于RNA结合蛋白和非编码RNA组合控制mRNA命运的文章；Iwasaki YW等2015年在Annual Review of Biochemistry上发表关于PIWI相互作用RNA生物合成与功能的综述；Jing L等2017年在Molecular Cancer上发表关于环状RNA的论文；参考文献列表包含多篇不同年份的文献。"}, "cards": [{"front": "Iwasaki YW等2015年综述的主题是什么？", "back": "PIWI相互作用RNA生物合成与功能。", "mnemonic": "PIWI RNA综述", "useImg": false}]}], "mcq": [{"id": "ch07_mcq_1", "mod": "第七章 非编码RNA", "modI": 0, "q": "下列关于非编码RNA（ncRNA）的描述，正确的是：", "o": ["A. 广义ncRNA不包括tRNA和rRNA", "B. 狭义ncRNA通常包括tRNA和rRNA", "C. 非编码RNA不编码蛋白质，直接在RNA水平发挥作用", "D. 非编码RNA在人类基因组转录产物中占比不足10%"], "a": "C", "e": "非编码RNA指不编码蛋白质、直接在RNA水平发挥作用的RNA。广义ncRNA包括tRNA和rRNA，狭义通常不包括；人类基因组约75%可转录，非编码RNA占总RNA约74%，远高于10%。", "kp": "ch07_s0_1"}, {"id": "ch07_mcq_2", "mod": "第七章 非编码RNA", "modI": 0, "q": "动物miRNA生物合成过程中，将pri-miRNA加工为pre-miRNA的酶是：", "o": ["A. Dicer", "B. Drosha", "C. Argonaute", "D. Exportin-5"], "a": "B", "e": "动物中pri-miRNA在核内被Drosha（RNaseⅢ类酶）及其辅因子DGCR8/Pasha加工为pre-miRNA；Dicer在胞浆中进一步加工为成熟miRNA；Exportin-5负责核输出；Argonaute是RISC组分。", "kp": "ch07_s0_7"}, {"id": "ch07_mcq_3", "mod": "第七章 非编码RNA", "modI": 0, "q": "植物miRNA合成与动物的主要区别之一是：", "o": ["A. 植物中存在Drosha同系物", "B. 植物中由DCL-1专一负责MIRNA加工", "C. 植物miRNA不加载Argonaute蛋白", "D. 植物miRNA不经过Dicer加工"], "a": "B", "e": "植物中未发现Drosha及其辅因子DGCR8/Pasha的同系物，基因研究显示Dicer like 1（DCL-1）专一负责MIRNA加工；植物miRNA仍加载Argonaute家族蛋白，也经过Dicer类酶加工。", "kp": "ch07_s0_7"}, {"id": "ch07_mcq_4", "mod": "第七章 非编码RNA", "modI": 0, "q": "关于circRNA的特性，下列描述错误的是：", "o": ["A. circRNA以共价键形成闭环结构，无PolyA尾巴", "B. circRNA在人类细胞中种类可达25000~100000种", "C. circRNA一般不易被RNase降解，且完全不能被siRNA降解", "D. circRNA由DNA转录而来，一般不翻译成蛋白质"], "a": "C", "e": "circRNA不易被RNase降解，但若siRNA对应的靶序列存在于circRNA中，circRNA仍可被siRNA降解，因此“完全不能”错误。其余选项均正确。", "kp": "ch07_s0_14"}, {"id": "ch07_mcq_5", "mod": "第七章 非编码RNA", "modI": 0, "q": "circRNA形成途径中，依赖反向互补motif（两端分别为GU富集片段和C富集片段）的是：", "o": ["A. 剪接体依赖的环化途径", "B. 内含子配对驱动的环化途径", "C. 套索驱动的环化途径", "D. 蛋白因子结合环化途径"], "a": "B", "e": "内含子配对驱动的环化途径依赖反向互补motif，motif两端分别是靠近5'端剪接位点的7nt GU富集片段和靠近分支位点的C富集片段，推动环状RNA生成。", "kp": "ch07_s0_14"}, {"id": "ch07_mcq_6", "mod": "第七章 非编码RNA", "modI": 0, "q": "siRNA生物合成中，负责将双链RNA加工为siRNA的酶是：", "o": ["A. Drosha", "B. Dicer", "C. RISC", "D. RNA聚合酶Ⅱ"], "a": "B", "e": "siRNA由Dicer（对双链RNA具有特异性的RNaseⅢ类酶）加工双链RNA（dsRNA）而成。Drosha主要参与miRNA的核内加工；RISC是沉默复合体；RNA聚合酶Ⅱ参与转录。", "kp": "ch07_s0_7"}, {"id": "ch07_mcq_7", "mod": "第七章 非编码RNA", "modI": 0, "q": "关于RNAi机制，下列描述正确的是：", "o": ["A. siRNA与靶mRNA的3'端必须完全匹配才能降解", "B. siRNA识别靶序列高度特异，中央碱基错配会严重抑制RNAi效应", "C. RISC切割靶mRNA不需要ATP参与", "D. siRNA是RNAi途径的最终产物，不参与RISC组装"], "a": "B", "e": "siRNA识别靶序列具有高度特异性，降解首先发生在相对于siRNA的中央位置，中央碱基错配会严重抑制RNAi效应；3'端核苷酸序列并不要求与靶mRNA完全匹配；RISC切割需要ATP参与；siRNA并入RISC中发挥作用。", "kp": "ch07_s0_17"}, {"id": "ch07_mcq_8", "mod": "第七章 非编码RNA", "modI": 0, "q": "下列哪项不是非编码RNA功能预测的常见方法？", "o": ["A. 通过互作、共表达、共定位信息进行功能富集", "B. 建立编码-非编码网络，划分功能模块并赋功能", "C. 通过序列预测ncRNA与RNA或蛋白质的结合情况", "D. 通过翻译产物进行质谱鉴定并推断功能"], "a": "D", "e": "非编码RNA缺乏翻译产物，因此不能通过翻译产物进行质谱鉴定来推断功能。其余三项均为ncRNA功能预测的常见理论方法。", "kp": "ch07_s0_6"}, {"id": "ch07_mcq_9", "mod": "第七章 非编码RNA", "modI": 0, "q": "关于snRNA的描述，正确的是：", "o": ["A. snRNA只存在于细胞质中", "B. snRNA是剪接体的主要成分，参与pre-mRNA剪接", "C. 所有snRNA均由RNA聚合酶Ⅲ转录", "D. snRNA不参与RNA加工，只参与蛋白质合成"], "a": "B", "e": "snRNA是真核生物转录后加工过程中剪接体的主要成分，与蛋白形成snRNP参与pre-mRNA剪接。snRNA主要存在于细胞核中；除U6由RNA聚合酶Ⅲ转录外，其余由RNA聚合酶Ⅱ转录；snRNA不参与蛋白质合成活动。", "kp": "ch07_s0_20"}, {"id": "ch07_mcq_10", "mod": "第七章 非编码RNA", "modI": 0, "q": "下列数据库中，专门整合Ribo-seq和RNA-seq数据来预测circRNA及其编码潜能的是：", "o": ["A. circBase", "B. CircNet", "C. CircPro", "D. deepBase v2.0"], "a": "C", "e": "CircPro提供一个pipeline，整合Ribo-seq和RNA-seq数据来预测circRNA及其编码潜能。circBase收集整合已发布circRNA数据；CircNet提供circRNA-miRNA-mRNA互作网络等；deepBase v2.0构建circRNA表达图谱。", "kp": "ch07_s0_16"}], "judge": [{"id": "ch07_judge_1", "modI": 0, "q": "非编码RNA（ncRNA）指不编码蛋白质、直接在RNA水平发挥作用的RNA，广义ncRNA包括tRNA和rRNA。", "a": "对", "e": "定义正确，广义ncRNA包括tRNA和rRNA，狭义通常不包括这两种。", "kp": "ch07_s0_0"}, {"id": "ch07_judge_2", "modI": 0, "q": "人类基因组约75%可转录，非编码RNA占总RNA约74%，蛋白质编码序列仅约1.5%。", "a": "对", "e": "数据与讲义一致。", "kp": "ch07_s0_0"}, {"id": "ch07_judge_3", "modI": 0, "q": "动物miRNA生物合成中，pri-miRNA在胞浆中被Drosha加工为pre-miRNA。", "a": "错", "e": "pri-miRNA在核内被Drosha及其辅因子DGCR8/Pasha加工为pre-miRNA，而非胞浆。", "kp": "ch07_s0_7"}, {"id": "ch07_judge_4", "modI": 0, "q": "植物miRNA合成中，Dicer like 1（DCL-1）专一负责MIRNA加工。", "a": "对", "e": "植物中未发现Drosha同系物，DCL-1专一负责MIRNA加工。", "kp": "ch07_s0_7"}, {"id": "ch07_judge_5", "modI": 0, "q": "circRNA具有5'端和3'端终点，也有PolyA尾巴。", "a": "错", "e": "circRNA以共价键形成闭环结构，无5'端和3'端终点，也无PolyA尾巴。", "kp": "ch07_s0_13"}, {"id": "ch07_judge_6", "modI": 0, "q": "circRNA通常由非经典可变剪接（反向剪接，back splicing）产生。", "a": "对", "e": "circRNA通常由反向剪接产生，主要有剪接体依赖、内含子配对驱动、套索驱动和蛋白因子结合4种途径。", "kp": "ch07_s0_13"}, {"id": "ch07_judge_7", "modI": 0, "q": "siRNA是21~25 nt的小RNA，由Dicer加工双链RNA而成，是RISC的主要成员。", "a": "对", "e": "描述正确。", "kp": "ch07_s0_7"}, {"id": "ch07_judge_8", "modI": 0, "q": "RNAi机制中，RISC利用核酸内切酶活性切割靶mRNA与反义链互补区域，形成21~23 nt siRNA。", "a": "对", "e": "描述正确。", "kp": "ch07_s0_17"}, {"id": "ch07_judge_9", "modI": 0, "q": "siRNA识别靶序列具有高度特异性，降解首先发生在相对于siRNA的中央位置，中央碱基错配会严重抑制RNAi效应。", "a": "对", "e": "描述正确。", "kp": "ch07_s0_17"}, {"id": "ch07_judge_10", "modI": 0, "q": "lncRNA具有跨物种高保守性、组织特异性表达和高丰度等特点。", "a": "错", "e": "lncRNA具有跨物种低保守性、组织特异性表达和低丰度等特点。", "kp": "ch07_s0_1"}], "fill": [{"id": "ch07_fill_1", "modI": 0, "q": "非编码RNA按长度分为短链ncRNA（<200 nt）和长链ncRNA（>200 nt），其中短链ncRNA包括miRNA、piRNA、siRNA、snRNA、snoRNA等，长链ncRNA包括lncRNA、circRNA等。人类基因组约________%可转录，非编码RNA占总RNA约________%。", "a": "75,74", "kp": "ch07_s0_0"}, {"id": "ch07_fill_2", "modI": 0, "q": "动物miRNA生物合成中，pri-miRNA在核内被________及其辅因子DGCR8/Pasha加工为pre-miRNA；pre-miRNA在________介导下转运至胞浆；在胞浆中由________加工为成熟miRNA，并加载到Argonaute蛋白生成RISC。", "a": "Drosha,exportin-5 (EXP-5),Dicer", "kp": "ch07_s0_7"}, {"id": "ch07_fill_3", "modI": 0, "q": "植物miRNA合成与动物不同：植物中未发现Drosha及其辅因子DGCR8/Pasha的同系物，表明植物不存在依赖Drosha的加工过程。基因研究显示________专一负责MIRNA加工；exportin-5由________介导miRNA从细胞核到细胞质；miRNA在细胞核或细胞质中加载Argonaute家族蛋白（AGO）。", "a": "Dicer like 1 (DCL-1),HASTY (HST)", "kp": "ch07_s0_7"}, {"id": "ch07_fill_4", "modI": 0, "q": "circRNA通常由非经典可变剪接（反向剪接，back splicing）产生，主要有4种途径：①________依赖的环化途径；②________驱动的环化途径；③________驱动的环化途径；④________结合环化途径。", "a": "剪接体,内含子配对,套索,蛋白因子", "kp": "ch07_s0_13"}, {"id": "ch07_fill_5", "modI": 0, "q": "siRNA是21~25 nt的小RNA，由________（对双链RNA特异的RNaseⅢ类酶）加工双链RNA（dsRNA）而成。siRNA是________的主要成员，激发与之互补的目标mRNA沉默。", "a": "Dicer,RISC", "kp": "ch07_s0_17"}, {"id": "ch07_fill_6", "modI": 0, "q": "RNAi机制：Rde-1识别外源dsRNA，引导其与Dicer结合形成酶-dsRNA复合体；Dicer作用下，dsRNA正义链被mRNA替换释放，在________参与下RISC利用核酸内切酶活性切割靶mRNA与反义链互补区域，形成21~23 nt siRNA。", "a": "ATP", "kp": "ch07_s0_17"}, {"id": "ch07_fill_7", "modI": 0, "q": "ncRNA大规模鉴定分为理论预测和实验方法。理论预测常用工具包括snoScan、snoGPS、tRNAScan、mirScan、RNAz和RNAmotif等，简便快捷但最终需________验证。实验方法包括构建ncRNA的cDNA文库、克隆测序、直接分离纯化后测序，以及全基因组________芯片技术。", "a": "实验,tiling array", "kp": "ch07_s0_1"}, {"id": "ch07_fill_8", "modI": 0, "q": "circRNA常用数据库和分析软件：①________，包含约15万circRNA基因（人、鼠、果蝇、线虫等），构建了较全面的circRNA表达图谱；②________，收集整合已发布circRNA数据；③CircNet，提供新circRNA鉴定、circRNA-miRNA-mRNA互作网络、亚型表达水平、基因组注释和序列；④CircPro，整合Ribo-seq和RNA-seq数据预测circRNA及其编码潜能；⑤miARma-Seq，综合分析软件。", "a": "deepBase v2.0,circBase", "kp": "ch07_s0_16"}], "short": [{"id": "ch07_short_1", "modI": 0, "q": "简述非编码RNA的定义与分类。", "a": "定义：非编码RNA（ncRNA）指不编码蛋白质、直接在RNA水平发挥作用的RNA。分类：①广义ncRNA包括tRNA和rRNA；狭义ncRNA通常不包括这两种。②按长度分为短链ncRNA（<200 nt，如miRNA、piRNA、siRNA、snRNA、snoRNA）和长链ncRNA（>200 nt，如lncRNA、circRNA）。③按细胞内分布可分为snoRNA、snRNA、scRNA、Cajal小体特异性小RNA等。人类基因组约75%可转录，非编码RNA占总RNA约74%，蛋白质编码序列仅约1.5%。ncRNA并非“垃圾RNA”，其核心功能是调控。", "kp": "ch07_s0_6"}, {"id": "ch07_short_2", "modI": 0, "q": "简述动物miRNA的生物合成过程及其负调控靶基因表达的机制。", "a": "动物miRNA基因多位于转录单元区，尤其内含子区，序列高度保守。miRNA为21~25 nt单链RNA，由发夹状初始转录产物加工而成。动物中：pri-miRNA在核内被Drosha（RNaseⅢ类酶）及其辅因子DGCR8/Pasha加工为pre-miRNA；pre-miRNA在exportin-5（EXP-5）介导下转运至胞浆；在胞浆中由Dicer（RNaseⅢ型蛋白）加工为成熟miRNA，并加载到Argonaute蛋白生成RISC。miRNA通过与靶基因3'UTR配对，促进mRNA降解或抑制翻译，从而负调控靶基因表达。", "kp": "ch07_s0_7"}, {"id": "ch07_short_3", "modI": 0, "q": "简述circRNA的生物合成途径。", "a": "circRNA通常由非经典可变剪接（反向剪接，back splicing）产生，主要有4种途径：①剪接体依赖的环化途径，snRNP装配后下游外显子5'供体位点与上游3'受体位点结合促进成环；②内含子配对驱动的环化途径，依赖反向互补motif，两端分别为GU富集片段和C富集片段；③套索驱动的环化途径，经典外显子跳跃产生套索副产物，被跳过区域经套索剪接形成外显子环状RNA；④蛋白因子结合环化途径，RBP结合内含子靶序列使供体-受体靠近促进环化，部分RBP可抑制环化。", "kp": "ch07_s0_14"}, {"id": "ch07_short_4", "modI": 0, "q": "简述siRNA的功能与RNAi机制。", "a": "siRNA为双股RNA，主要参与RNA干扰（RNAi），以专一性方式调节基因表达，也参与抗病毒、染色质结构改变等。其生理意义包括生物抗御机制、调控细胞分化与胚胎发育、维持基因组稳定及RNA水平调控。RNAi机制：Rde-1识别外源dsRNA，引导其与Dicer结合形成酶-dsRNA复合体；Dicer作用下，dsRNA正义链被mRNA替换释放，在ATP参与下RISC利用核酸内切酶活性切割靶mRNA与反义链互补区域，形成21~23 nt siRNA。siRNA并入RISC后与靶标基因编码区或UTR完全配对，降解靶标基因，是典型负调控。", "kp": "ch07_s0_17"}, {"id": "ch07_short_5", "modI": 0, "q": "简述非编码RNA功能预测的常见方法。", "a": "由于ncRNA缺乏翻译产物且数量庞大，功能预测主要依赖理论手段。常见方法：①通过互作、共表达、共定位等信息获得相关基因及互作因子，进行功能富集，需结合多种因素并注意统计检验；②收集功能注释与相关性数据，建立编码-非编码网络，划分功能模块并为模块内ncRNA赋功能；③通过序列预测ncRNA与RNA或蛋白质的结合情况，再推测功能，常用于预测lncRNA与miRNA的匹配关系（ceRNA角色）。常用平台包括ncFANs、ChIPBase、starBase、LncRNADisease、DIANA-LncBase等。", "kp": "ch07_s0_6"}], "calc": [{"id": "ch07_calc_1", "modI": 0, "q": "论述非编码RNA的识别方法及其优缺点。", "a": "ncRNA大规模鉴定分为理论预测和实验方法。理论预测从已知ncRNA提取特征，进行全基因组搜索，常用工具包括snoScan、snoGPS、tRNAScan、mirScan、RNAz和RNAmotif等，简便快捷但最终需实验验证。实验方法包括构建ncRNA的cDNA文库、克隆测序、直接分离纯化后测序，以及全基因组tiling array芯片技术。在长非编码RNA专用芯片推出前，可对已有芯片探针重注释以识别lncRNA表达。理论预测可快速全基因组筛选，但假阳性较高；实验方法更可靠，但通量低、成本高。两者结合可提高鉴定准确性。", "steps": "1. 理论预测：从已知ncRNA提取特征，全基因组搜索，常用工具snoScan、snoGPS、tRNAScan、mirScan、RNAz、RNAmotif等；简便快捷但需实验验证。2. 实验方法：构建cDNA文库、克隆测序、直接分离纯化后测序、全基因组tiling array芯片技术。3. 长非编码RNA专用芯片推出前，可对已有芯片探针重注释以识别lncRNA表达。4. 优缺点：理论预测快速全基因组筛选但假阳性较高；实验方法可靠但通量低、成本高；两者结合提高准确性。", "kp": "ch07_s0_3"}, {"id": "ch07_calc_2", "modI": 0, "q": "论述circRNA的特性及其生物学意义。", "a": "circRNA含量丰富，人类细胞中可达25000~100000种，数量远超线性RNA；不同物种间通常具有一定进化保守性，但也有一些不保守。circRNA由DNA转录而来，一般不翻译成蛋白质；不易被RNase降解，但若siRNA靶序列存在于circRNA中，仍可被siRNA降解；当siRNA作用于线性RNA末端时，拥有共同靶序列的circRNA可能不受影响。circRNA的发现解释了以往基因序列“混乱”现象，如外显子顺序打乱、无内含子基因也能生成circRNA等。其调控复杂性及在疾病发生中的重要作用日益受到重视。", "steps": "1. 含量丰富：人类细胞中可达25000~100000种，数量远超线性RNA。2. 进化保守性：不同物种间通常具有一定进化保守性，但也有一些不保守。3. 不翻译：由DNA转录而来，一般不翻译成蛋白质。4. 稳定性：不易被RNase降解；但若siRNA靶序列存在于circRNA中，仍可被siRNA降解；当siRNA作用于线性RNA末端时，拥有共同靶序列的circRNA可能不受影响。5. 生物学意义：解释以往基因序列“混乱”现象，如外显子顺序打乱、无内含子基因也能生成circRNA等；调控复杂性及在疾病发生中的重要作用日益受到重视。", "kp": "ch07_s0_14"}], "term": [{"id": "ch07_term_1", "modI": 0, "term": "non-coding RNA (ncRNA)", "def": "不编码蛋白质、直接在RNA水平发挥作用的RNA。广义包括tRNA和rRNA；狭义通常不包括tRNA和rRNA。按长度分为短链ncRNA（<200 nt，如miRNA、piRNA、siRNA、snRNA、snoRNA）和长链ncRNA（>200 nt，如lncRNA、circRNA）。人类基因组约75%可转录，非编码RNA占总RNA约74%，蛋白质编码序列仅约1.5%。核心功能是调控，RNAi现象获2006年诺贝尔奖。", "kp": "ch07_s0_2"}, {"id": "ch07_term_2", "modI": 0, "term": "miRNA", "def": "微小RNA，21~25 nt单链RNA，由发夹状初始转录产物加工而成。动物中pri-miRNA在核内被Drosha/DGCR8加工为pre-miRNA，经exportin-5转运至胞浆，由Dicer加工为成熟miRNA并加载到Argonaute蛋白生成RISC。通过与靶基因3'UTR配对，促进mRNA降解或抑制翻译，负调控靶基因表达。miRBase release 21收录人类miRNA约2588个，异常与癌症相关。", "kp": "ch07_s0_1"}, {"id": "ch07_term_3", "modI": 0, "term": "lncRNA", "def": "长链非编码RNA，长度>200 nt。可与染色质重塑复合物结合，定位到特定基因位点，改变DNA甲基化和组蛋白状态，参与表观遗传调控；也能在转录及转录后水平调节蛋白编码基因表达。有带PolyA尾和不带PolyA尾两种形式，具有跨物种低保守性、组织特异性表达和低丰度等特点。", "kp": "ch07_s0_1"}, {"id": "ch07_term_4", "modI": 0, "term": "circRNA", "def": "环状RNA，以共价键形成闭环结构，无5'端和3'端终点，也无PolyA尾巴。通常由非经典可变剪接（反向剪接）产生，主要有剪接体依赖、内含子配对驱动、套索驱动和蛋白因子结合4种途径。含量丰富，人类细胞中可达25000~100000种；不同物种间通常具有一定进化保守性；一般不翻译成蛋白质；不易被RNase降解，但若siRNA靶序列存在于circRNA中仍可被siRNA降解。", "kp": "ch07_s0_13"}, {"id": "ch07_term_5", "modI": 0, "term": "siRNA", "def": "小干扰RNA，21~25 nt的小RNA，由Dicer（对双链RNA特异的RNaseⅢ类酶）加工双链RNA而成。是RISC的主要成员，激发与之互补的目标mRNA沉默。主要参与RNA干扰，以专一性方式调节基因表达，也参与抗病毒、染色质结构改变等。siRNA并入RISC后与靶标基因编码区或UTR完全配对，降解靶标基因，是典型负调控。", "kp": "ch07_s0_17"}, {"id": "ch07_term_6", "modI": 0, "term": "piRNA", "def": "PIWI相互作用RNA，属于短链非编码RNA（<200 nt）。与PIWI蛋白家族结合，主要在生殖细胞中表达，参与转座子沉默、基因组稳定维持和生殖发育调控。", "kp": "ch07_s0_18"}, {"id": "ch07_term_7", "modI": 0, "term": "snoRNA", "def": "核仁小RNA，多富集于核仁，大小60~400 nt，需与特定蛋白结合成snoRNP行使功能，具有保守序列元件。参与rRNA前体的加工、修饰（如2'-O-核糖甲基化和假尿嘧啶形成）及核糖体组装。", "kp": "ch07_s0_4"}, {"id": "ch07_term_8", "modI": 0, "term": "snRNA", "def": "细胞核小分子RNA，长度100~300 nt，是剪接体主要成分，与蛋白形成snRNP参与pre-mRNA剪接。分为U1~U7，除U6由RNA聚合酶Ⅲ转录外其余由RNA聚合酶Ⅱ转录，5'端有TMG帽，3'端有Sm结合位点。", "kp": "ch07_s0_4"}, {"id": "ch07_term_9", "modI": 0, "term": "scRNA", "def": "细胞质小分子RNA，分布在细胞质，主要在蛋白质合成中起作用。", "kp": "ch07_s0_1"}, {"id": "ch07_term_10", "modI": 0, "term": "Cajal body-specific small RNA", "def": "Cajal小体（CBs）特异性小RNA，参与snRNA位点特异性2'-O-核糖甲基化及假尿嘧啶形成。", "kp": "ch07_s0_5"}, {"id": "ch07_term_11", "modI": 0, "term": "RNA interference (RNAi)", "def": "RNA干扰，由双链RNA引发的转录后基因沉默现象。机制：Rde-1识别外源dsRNA，引导其与Dicer结合形成酶-dsRNA复合体；Dicer作用下，dsRNA正义链被mRNA替换释放，在ATP参与下RISC利用核酸内切酶活性切割靶mRNA与反义链互补区域，形成21~23 nt siRNA。siRNA并入RISC后与靶标基因编码区或UTR完全配对，降解靶标基因，是典型负调控。", "kp": "ch07_s0_0"}, {"id": "ch07_term_12", "modI": 0, "term": "ceRNA", "def": "竞争性内源RNA，通过序列预测ncRNA与RNA或蛋白质的结合情况，再推测功能，常用于预测lncRNA与miRNA的匹配关系。lncRNA可作为ceRNA吸附miRNA，从而间接调控miRNA靶基因表达。", "kp": "ch07_s0_0"}]}], "mcq": [{"id": "ch07_mcq_1", "mod": "第七章 非编码RNA", "modI": 0, "q": "下列关于非编码RNA（ncRNA）的描述，正确的是：", "o": ["A. 广义ncRNA不包括tRNA和rRNA", "B. 狭义ncRNA通常包括tRNA和rRNA", "C. 非编码RNA不编码蛋白质，直接在RNA水平发挥作用", "D. 非编码RNA在人类基因组转录产物中占比不足10%"], "a": "C", "e": "非编码RNA指不编码蛋白质、直接在RNA水平发挥作用的RNA。广义ncRNA包括tRNA和rRNA，狭义通常不包括；人类基因组约75%可转录，非编码RNA占总RNA约74%，远高于10%。", "kp": "ch07_s0_1"}, {"id": "ch07_mcq_2", "mod": "第七章 非编码RNA", "modI": 0, "q": "动物miRNA生物合成过程中，将pri-miRNA加工为pre-miRNA的酶是：", "o": ["A. Dicer", "B. Drosha", "C. Argonaute", "D. Exportin-5"], "a": "B", "e": "动物中pri-miRNA在核内被Drosha（RNaseⅢ类酶）及其辅因子DGCR8/Pasha加工为pre-miRNA；Dicer在胞浆中进一步加工为成熟miRNA；Exportin-5负责核输出；Argonaute是RISC组分。", "kp": "ch07_s0_7"}, {"id": "ch07_mcq_3", "mod": "第七章 非编码RNA", "modI": 0, "q": "植物miRNA合成与动物的主要区别之一是：", "o": ["A. 植物中存在Drosha同系物", "B. 植物中由DCL-1专一负责MIRNA加工", "C. 植物miRNA不加载Argonaute蛋白", "D. 植物miRNA不经过Dicer加工"], "a": "B", "e": "植物中未发现Drosha及其辅因子DGCR8/Pasha的同系物，基因研究显示Dicer like 1（DCL-1）专一负责MIRNA加工；植物miRNA仍加载Argonaute家族蛋白，也经过Dicer类酶加工。", "kp": "ch07_s0_7"}, {"id": "ch07_mcq_4", "mod": "第七章 非编码RNA", "modI": 0, "q": "关于circRNA的特性，下列描述错误的是：", "o": ["A. circRNA以共价键形成闭环结构，无PolyA尾巴", "B. circRNA在人类细胞中种类可达25000~100000种", "C. circRNA一般不易被RNase降解，且完全不能被siRNA降解", "D. circRNA由DNA转录而来，一般不翻译成蛋白质"], "a": "C", "e": "circRNA不易被RNase降解，但若siRNA对应的靶序列存在于circRNA中，circRNA仍可被siRNA降解，因此“完全不能”错误。其余选项均正确。", "kp": "ch07_s0_14"}, {"id": "ch07_mcq_5", "mod": "第七章 非编码RNA", "modI": 0, "q": "circRNA形成途径中，依赖反向互补motif（两端分别为GU富集片段和C富集片段）的是：", "o": ["A. 剪接体依赖的环化途径", "B. 内含子配对驱动的环化途径", "C. 套索驱动的环化途径", "D. 蛋白因子结合环化途径"], "a": "B", "e": "内含子配对驱动的环化途径依赖反向互补motif，motif两端分别是靠近5'端剪接位点的7nt GU富集片段和靠近分支位点的C富集片段，推动环状RNA生成。", "kp": "ch07_s0_14"}, {"id": "ch07_mcq_6", "mod": "第七章 非编码RNA", "modI": 0, "q": "siRNA生物合成中，负责将双链RNA加工为siRNA的酶是：", "o": ["A. Drosha", "B. Dicer", "C. RISC", "D. RNA聚合酶Ⅱ"], "a": "B", "e": "siRNA由Dicer（对双链RNA具有特异性的RNaseⅢ类酶）加工双链RNA（dsRNA）而成。Drosha主要参与miRNA的核内加工；RISC是沉默复合体；RNA聚合酶Ⅱ参与转录。", "kp": "ch07_s0_7"}, {"id": "ch07_mcq_7", "mod": "第七章 非编码RNA", "modI": 0, "q": "关于RNAi机制，下列描述正确的是：", "o": ["A. siRNA与靶mRNA的3'端必须完全匹配才能降解", "B. siRNA识别靶序列高度特异，中央碱基错配会严重抑制RNAi效应", "C. RISC切割靶mRNA不需要ATP参与", "D. siRNA是RNAi途径的最终产物，不参与RISC组装"], "a": "B", "e": "siRNA识别靶序列具有高度特异性，降解首先发生在相对于siRNA的中央位置，中央碱基错配会严重抑制RNAi效应；3'端核苷酸序列并不要求与靶mRNA完全匹配；RISC切割需要ATP参与；siRNA并入RISC中发挥作用。", "kp": "ch07_s0_17"}, {"id": "ch07_mcq_8", "mod": "第七章 非编码RNA", "modI": 0, "q": "下列哪项不是非编码RNA功能预测的常见方法？", "o": ["A. 通过互作、共表达、共定位信息进行功能富集", "B. 建立编码-非编码网络，划分功能模块并赋功能", "C. 通过序列预测ncRNA与RNA或蛋白质的结合情况", "D. 通过翻译产物进行质谱鉴定并推断功能"], "a": "D", "e": "非编码RNA缺乏翻译产物，因此不能通过翻译产物进行质谱鉴定来推断功能。其余三项均为ncRNA功能预测的常见理论方法。", "kp": "ch07_s0_6"}, {"id": "ch07_mcq_9", "mod": "第七章 非编码RNA", "modI": 0, "q": "关于snRNA的描述，正确的是：", "o": ["A. snRNA只存在于细胞质中", "B. snRNA是剪接体的主要成分，参与pre-mRNA剪接", "C. 所有snRNA均由RNA聚合酶Ⅲ转录", "D. snRNA不参与RNA加工，只参与蛋白质合成"], "a": "B", "e": "snRNA是真核生物转录后加工过程中剪接体的主要成分，与蛋白形成snRNP参与pre-mRNA剪接。snRNA主要存在于细胞核中；除U6由RNA聚合酶Ⅲ转录外，其余由RNA聚合酶Ⅱ转录；snRNA不参与蛋白质合成活动。", "kp": "ch07_s0_20"}, {"id": "ch07_mcq_10", "mod": "第七章 非编码RNA", "modI": 0, "q": "下列数据库中，专门整合Ribo-seq和RNA-seq数据来预测circRNA及其编码潜能的是：", "o": ["A. circBase", "B. CircNet", "C. CircPro", "D. deepBase v2.0"], "a": "C", "e": "CircPro提供一个pipeline，整合Ribo-seq和RNA-seq数据来预测circRNA及其编码潜能。circBase收集整合已发布circRNA数据；CircNet提供circRNA-miRNA-mRNA互作网络等；deepBase v2.0构建circRNA表达图谱。", "kp": "ch07_s0_16"}], "judge": [{"id": "ch07_judge_1", "modI": 0, "q": "非编码RNA（ncRNA）指不编码蛋白质、直接在RNA水平发挥作用的RNA，广义ncRNA包括tRNA和rRNA。", "a": "对", "e": "定义正确，广义ncRNA包括tRNA和rRNA，狭义通常不包括这两种。", "kp": "ch07_s0_0"}, {"id": "ch07_judge_2", "modI": 0, "q": "人类基因组约75%可转录，非编码RNA占总RNA约74%，蛋白质编码序列仅约1.5%。", "a": "对", "e": "数据与讲义一致。", "kp": "ch07_s0_0"}, {"id": "ch07_judge_3", "modI": 0, "q": "动物miRNA生物合成中，pri-miRNA在胞浆中被Drosha加工为pre-miRNA。", "a": "错", "e": "pri-miRNA在核内被Drosha及其辅因子DGCR8/Pasha加工为pre-miRNA，而非胞浆。", "kp": "ch07_s0_7"}, {"id": "ch07_judge_4", "modI": 0, "q": "植物miRNA合成中，Dicer like 1（DCL-1）专一负责MIRNA加工。", "a": "对", "e": "植物中未发现Drosha同系物，DCL-1专一负责MIRNA加工。", "kp": "ch07_s0_7"}, {"id": "ch07_judge_5", "modI": 0, "q": "circRNA具有5'端和3'端终点，也有PolyA尾巴。", "a": "错", "e": "circRNA以共价键形成闭环结构，无5'端和3'端终点，也无PolyA尾巴。", "kp": "ch07_s0_13"}, {"id": "ch07_judge_6", "modI": 0, "q": "circRNA通常由非经典可变剪接（反向剪接，back splicing）产生。", "a": "对", "e": "circRNA通常由反向剪接产生，主要有剪接体依赖、内含子配对驱动、套索驱动和蛋白因子结合4种途径。", "kp": "ch07_s0_13"}, {"id": "ch07_judge_7", "modI": 0, "q": "siRNA是21~25 nt的小RNA，由Dicer加工双链RNA而成，是RISC的主要成员。", "a": "对", "e": "描述正确。", "kp": "ch07_s0_7"}, {"id": "ch07_judge_8", "modI": 0, "q": "RNAi机制中，RISC利用核酸内切酶活性切割靶mRNA与反义链互补区域，形成21~23 nt siRNA。", "a": "对", "e": "描述正确。", "kp": "ch07_s0_17"}, {"id": "ch07_judge_9", "modI": 0, "q": "siRNA识别靶序列具有高度特异性，降解首先发生在相对于siRNA的中央位置，中央碱基错配会严重抑制RNAi效应。", "a": "对", "e": "描述正确。", "kp": "ch07_s0_17"}, {"id": "ch07_judge_10", "modI": 0, "q": "lncRNA具有跨物种高保守性、组织特异性表达和高丰度等特点。", "a": "错", "e": "lncRNA具有跨物种低保守性、组织特异性表达和低丰度等特点。", "kp": "ch07_s0_1"}], "fill": [{"id": "ch07_fill_1", "modI": 0, "q": "非编码RNA按长度分为短链ncRNA（<200 nt）和长链ncRNA（>200 nt），其中短链ncRNA包括miRNA、piRNA、siRNA、snRNA、snoRNA等，长链ncRNA包括lncRNA、circRNA等。人类基因组约________%可转录，非编码RNA占总RNA约________%。", "a": "75,74", "kp": "ch07_s0_0"}, {"id": "ch07_fill_2", "modI": 0, "q": "动物miRNA生物合成中，pri-miRNA在核内被________及其辅因子DGCR8/Pasha加工为pre-miRNA；pre-miRNA在________介导下转运至胞浆；在胞浆中由________加工为成熟miRNA，并加载到Argonaute蛋白生成RISC。", "a": "Drosha,exportin-5 (EXP-5),Dicer", "kp": "ch07_s0_7"}, {"id": "ch07_fill_3", "modI": 0, "q": "植物miRNA合成与动物不同：植物中未发现Drosha及其辅因子DGCR8/Pasha的同系物，表明植物不存在依赖Drosha的加工过程。基因研究显示________专一负责MIRNA加工；exportin-5由________介导miRNA从细胞核到细胞质；miRNA在细胞核或细胞质中加载Argonaute家族蛋白（AGO）。", "a": "Dicer like 1 (DCL-1),HASTY (HST)", "kp": "ch07_s0_7"}, {"id": "ch07_fill_4", "modI": 0, "q": "circRNA通常由非经典可变剪接（反向剪接，back splicing）产生，主要有4种途径：①________依赖的环化途径；②________驱动的环化途径；③________驱动的环化途径；④________结合环化途径。", "a": "剪接体,内含子配对,套索,蛋白因子", "kp": "ch07_s0_13"}, {"id": "ch07_fill_5", "modI": 0, "q": "siRNA是21~25 nt的小RNA，由________（对双链RNA特异的RNaseⅢ类酶）加工双链RNA（dsRNA）而成。siRNA是________的主要成员，激发与之互补的目标mRNA沉默。", "a": "Dicer,RISC", "kp": "ch07_s0_17"}, {"id": "ch07_fill_6", "modI": 0, "q": "RNAi机制：Rde-1识别外源dsRNA，引导其与Dicer结合形成酶-dsRNA复合体；Dicer作用下，dsRNA正义链被mRNA替换释放，在________参与下RISC利用核酸内切酶活性切割靶mRNA与反义链互补区域，形成21~23 nt siRNA。", "a": "ATP", "kp": "ch07_s0_17"}, {"id": "ch07_fill_7", "modI": 0, "q": "ncRNA大规模鉴定分为理论预测和实验方法。理论预测常用工具包括snoScan、snoGPS、tRNAScan、mirScan、RNAz和RNAmotif等，简便快捷但最终需________验证。实验方法包括构建ncRNA的cDNA文库、克隆测序、直接分离纯化后测序，以及全基因组________芯片技术。", "a": "实验,tiling array", "kp": "ch07_s0_1"}, {"id": "ch07_fill_8", "modI": 0, "q": "circRNA常用数据库和分析软件：①________，包含约15万circRNA基因（人、鼠、果蝇、线虫等），构建了较全面的circRNA表达图谱；②________，收集整合已发布circRNA数据；③CircNet，提供新circRNA鉴定、circRNA-miRNA-mRNA互作网络、亚型表达水平、基因组注释和序列；④CircPro，整合Ribo-seq和RNA-seq数据预测circRNA及其编码潜能；⑤miARma-Seq，综合分析软件。", "a": "deepBase v2.0,circBase", "kp": "ch07_s0_16"}], "short": [{"id": "ch07_short_1", "modI": 0, "q": "简述非编码RNA的定义与分类。", "a": "定义：非编码RNA（ncRNA）指不编码蛋白质、直接在RNA水平发挥作用的RNA。分类：①广义ncRNA包括tRNA和rRNA；狭义ncRNA通常不包括这两种。②按长度分为短链ncRNA（<200 nt，如miRNA、piRNA、siRNA、snRNA、snoRNA）和长链ncRNA（>200 nt，如lncRNA、circRNA）。③按细胞内分布可分为snoRNA、snRNA、scRNA、Cajal小体特异性小RNA等。人类基因组约75%可转录，非编码RNA占总RNA约74%，蛋白质编码序列仅约1.5%。ncRNA并非“垃圾RNA”，其核心功能是调控。", "kp": "ch07_s0_6"}, {"id": "ch07_short_2", "modI": 0, "q": "简述动物miRNA的生物合成过程及其负调控靶基因表达的机制。", "a": "动物miRNA基因多位于转录单元区，尤其内含子区，序列高度保守。miRNA为21~25 nt单链RNA，由发夹状初始转录产物加工而成。动物中：pri-miRNA在核内被Drosha（RNaseⅢ类酶）及其辅因子DGCR8/Pasha加工为pre-miRNA；pre-miRNA在exportin-5（EXP-5）介导下转运至胞浆；在胞浆中由Dicer（RNaseⅢ型蛋白）加工为成熟miRNA，并加载到Argonaute蛋白生成RISC。miRNA通过与靶基因3'UTR配对，促进mRNA降解或抑制翻译，从而负调控靶基因表达。", "kp": "ch07_s0_7"}, {"id": "ch07_short_3", "modI": 0, "q": "简述circRNA的生物合成途径。", "a": "circRNA通常由非经典可变剪接（反向剪接，back splicing）产生，主要有4种途径：①剪接体依赖的环化途径，snRNP装配后下游外显子5'供体位点与上游3'受体位点结合促进成环；②内含子配对驱动的环化途径，依赖反向互补motif，两端分别为GU富集片段和C富集片段；③套索驱动的环化途径，经典外显子跳跃产生套索副产物，被跳过区域经套索剪接形成外显子环状RNA；④蛋白因子结合环化途径，RBP结合内含子靶序列使供体-受体靠近促进环化，部分RBP可抑制环化。", "kp": "ch07_s0_14"}, {"id": "ch07_short_4", "modI": 0, "q": "简述siRNA的功能与RNAi机制。", "a": "siRNA为双股RNA，主要参与RNA干扰（RNAi），以专一性方式调节基因表达，也参与抗病毒、染色质结构改变等。其生理意义包括生物抗御机制、调控细胞分化与胚胎发育、维持基因组稳定及RNA水平调控。RNAi机制：Rde-1识别外源dsRNA，引导其与Dicer结合形成酶-dsRNA复合体；Dicer作用下，dsRNA正义链被mRNA替换释放，在ATP参与下RISC利用核酸内切酶活性切割靶mRNA与反义链互补区域，形成21~23 nt siRNA。siRNA并入RISC后与靶标基因编码区或UTR完全配对，降解靶标基因，是典型负调控。", "kp": "ch07_s0_17"}, {"id": "ch07_short_5", "modI": 0, "q": "简述非编码RNA功能预测的常见方法。", "a": "由于ncRNA缺乏翻译产物且数量庞大，功能预测主要依赖理论手段。常见方法：①通过互作、共表达、共定位等信息获得相关基因及互作因子，进行功能富集，需结合多种因素并注意统计检验；②收集功能注释与相关性数据，建立编码-非编码网络，划分功能模块并为模块内ncRNA赋功能；③通过序列预测ncRNA与RNA或蛋白质的结合情况，再推测功能，常用于预测lncRNA与miRNA的匹配关系（ceRNA角色）。常用平台包括ncFANs、ChIPBase、starBase、LncRNADisease、DIANA-LncBase等。", "kp": "ch07_s0_6"}], "calc": [{"id": "ch07_calc_1", "modI": 0, "q": "论述非编码RNA的识别方法及其优缺点。", "a": "ncRNA大规模鉴定分为理论预测和实验方法。理论预测从已知ncRNA提取特征，进行全基因组搜索，常用工具包括snoScan、snoGPS、tRNAScan、mirScan、RNAz和RNAmotif等，简便快捷但最终需实验验证。实验方法包括构建ncRNA的cDNA文库、克隆测序、直接分离纯化后测序，以及全基因组tiling array芯片技术。在长非编码RNA专用芯片推出前，可对已有芯片探针重注释以识别lncRNA表达。理论预测可快速全基因组筛选，但假阳性较高；实验方法更可靠，但通量低、成本高。两者结合可提高鉴定准确性。", "steps": "1. 理论预测：从已知ncRNA提取特征，全基因组搜索，常用工具snoScan、snoGPS、tRNAScan、mirScan、RNAz、RNAmotif等；简便快捷但需实验验证。2. 实验方法：构建cDNA文库、克隆测序、直接分离纯化后测序、全基因组tiling array芯片技术。3. 长非编码RNA专用芯片推出前，可对已有芯片探针重注释以识别lncRNA表达。4. 优缺点：理论预测快速全基因组筛选但假阳性较高；实验方法可靠但通量低、成本高；两者结合提高准确性。", "kp": "ch07_s0_3"}, {"id": "ch07_calc_2", "modI": 0, "q": "论述circRNA的特性及其生物学意义。", "a": "circRNA含量丰富，人类细胞中可达25000~100000种，数量远超线性RNA；不同物种间通常具有一定进化保守性，但也有一些不保守。circRNA由DNA转录而来，一般不翻译成蛋白质；不易被RNase降解，但若siRNA靶序列存在于circRNA中，仍可被siRNA降解；当siRNA作用于线性RNA末端时，拥有共同靶序列的circRNA可能不受影响。circRNA的发现解释了以往基因序列“混乱”现象，如外显子顺序打乱、无内含子基因也能生成circRNA等。其调控复杂性及在疾病发生中的重要作用日益受到重视。", "steps": "1. 含量丰富：人类细胞中可达25000~100000种，数量远超线性RNA。2. 进化保守性：不同物种间通常具有一定进化保守性，但也有一些不保守。3. 不翻译：由DNA转录而来，一般不翻译成蛋白质。4. 稳定性：不易被RNase降解；但若siRNA靶序列存在于circRNA中，仍可被siRNA降解；当siRNA作用于线性RNA末端时，拥有共同靶序列的circRNA可能不受影响。5. 生物学意义：解释以往基因序列“混乱”现象，如外显子顺序打乱、无内含子基因也能生成circRNA等；调控复杂性及在疾病发生中的重要作用日益受到重视。", "kp": "ch07_s0_14"}], "term": [{"id": "ch07_term_1", "modI": 0, "term": "non-coding RNA (ncRNA)", "def": "不编码蛋白质、直接在RNA水平发挥作用的RNA。广义包括tRNA和rRNA；狭义通常不包括tRNA和rRNA。按长度分为短链ncRNA（<200 nt，如miRNA、piRNA、siRNA、snRNA、snoRNA）和长链ncRNA（>200 nt，如lncRNA、circRNA）。人类基因组约75%可转录，非编码RNA占总RNA约74%，蛋白质编码序列仅约1.5%。核心功能是调控，RNAi现象获2006年诺贝尔奖。", "kp": "ch07_s0_2"}, {"id": "ch07_term_2", "modI": 0, "term": "miRNA", "def": "微小RNA，21~25 nt单链RNA，由发夹状初始转录产物加工而成。动物中pri-miRNA在核内被Drosha/DGCR8加工为pre-miRNA，经exportin-5转运至胞浆，由Dicer加工为成熟miRNA并加载到Argonaute蛋白生成RISC。通过与靶基因3'UTR配对，促进mRNA降解或抑制翻译，负调控靶基因表达。miRBase release 21收录人类miRNA约2588个，异常与癌症相关。", "kp": "ch07_s0_1"}, {"id": "ch07_term_3", "modI": 0, "term": "lncRNA", "def": "长链非编码RNA，长度>200 nt。可与染色质重塑复合物结合，定位到特定基因位点，改变DNA甲基化和组蛋白状态，参与表观遗传调控；也能在转录及转录后水平调节蛋白编码基因表达。有带PolyA尾和不带PolyA尾两种形式，具有跨物种低保守性、组织特异性表达和低丰度等特点。", "kp": "ch07_s0_1"}, {"id": "ch07_term_4", "modI": 0, "term": "circRNA", "def": "环状RNA，以共价键形成闭环结构，无5'端和3'端终点，也无PolyA尾巴。通常由非经典可变剪接（反向剪接）产生，主要有剪接体依赖、内含子配对驱动、套索驱动和蛋白因子结合4种途径。含量丰富，人类细胞中可达25000~100000种；不同物种间通常具有一定进化保守性；一般不翻译成蛋白质；不易被RNase降解，但若siRNA靶序列存在于circRNA中仍可被siRNA降解。", "kp": "ch07_s0_13"}, {"id": "ch07_term_5", "modI": 0, "term": "siRNA", "def": "小干扰RNA，21~25 nt的小RNA，由Dicer（对双链RNA特异的RNaseⅢ类酶）加工双链RNA而成。是RISC的主要成员，激发与之互补的目标mRNA沉默。主要参与RNA干扰，以专一性方式调节基因表达，也参与抗病毒、染色质结构改变等。siRNA并入RISC后与靶标基因编码区或UTR完全配对，降解靶标基因，是典型负调控。", "kp": "ch07_s0_17"}, {"id": "ch07_term_6", "modI": 0, "term": "piRNA", "def": "PIWI相互作用RNA，属于短链非编码RNA（<200 nt）。与PIWI蛋白家族结合，主要在生殖细胞中表达，参与转座子沉默、基因组稳定维持和生殖发育调控。", "kp": "ch07_s0_18"}, {"id": "ch07_term_7", "modI": 0, "term": "snoRNA", "def": "核仁小RNA，多富集于核仁，大小60~400 nt，需与特定蛋白结合成snoRNP行使功能，具有保守序列元件。参与rRNA前体的加工、修饰（如2'-O-核糖甲基化和假尿嘧啶形成）及核糖体组装。", "kp": "ch07_s0_4"}, {"id": "ch07_term_8", "modI": 0, "term": "snRNA", "def": "细胞核小分子RNA，长度100~300 nt，是剪接体主要成分，与蛋白形成snRNP参与pre-mRNA剪接。分为U1~U7，除U6由RNA聚合酶Ⅲ转录外其余由RNA聚合酶Ⅱ转录，5'端有TMG帽，3'端有Sm结合位点。", "kp": "ch07_s0_4"}, {"id": "ch07_term_9", "modI": 0, "term": "scRNA", "def": "细胞质小分子RNA，分布在细胞质，主要在蛋白质合成中起作用。", "kp": "ch07_s0_1"}, {"id": "ch07_term_10", "modI": 0, "term": "Cajal body-specific small RNA", "def": "Cajal小体（CBs）特异性小RNA，参与snRNA位点特异性2'-O-核糖甲基化及假尿嘧啶形成。", "kp": "ch07_s0_5"}, {"id": "ch07_term_11", "modI": 0, "term": "RNA interference (RNAi)", "def": "RNA干扰，由双链RNA引发的转录后基因沉默现象。机制：Rde-1识别外源dsRNA，引导其与Dicer结合形成酶-dsRNA复合体；Dicer作用下，dsRNA正义链被mRNA替换释放，在ATP参与下RISC利用核酸内切酶活性切割靶mRNA与反义链互补区域，形成21~23 nt siRNA。siRNA并入RISC后与靶标基因编码区或UTR完全配对，降解靶标基因，是典型负调控。", "kp": "ch07_s0_0"}, {"id": "ch07_term_12", "modI": 0, "term": "ceRNA", "def": "竞争性内源RNA，通过序列预测ncRNA与RNA或蛋白质的结合情况，再推测功能，常用于预测lncRNA与miRNA的匹配关系。lncRNA可作为ceRNA吸附miRNA，从而间接调控miRNA靶基因表达。", "kp": "ch07_s0_0"}], "preview": {"main": "本章围绕非编码RNA（ncRNA）展开，先介绍其概念、基本特征与分类，再重点讲解miRNA、lncRNA、circRNA、siRNA、piRNA、snoRNA和snRNA等类型。主线是：ncRNA不编码蛋白质或编码潜能被重新认识，在转录、转录后和翻译水平广泛调控基因表达；生物信息学通过miRBase、NONCODE、LNCipedia、psRNATarget、降解组测序和circRNA数据库等资源，实现序列获取、分类注释、靶基因预测与功能挖掘。", "questions": ["非编码RNA的广义和狭义定义有什么区别？为什么说“非编码RNA不编码蛋白质”并不绝对？", "miRNA在动物和植物中的加工途径和靶基因调控方式有何异同？降解组测序为什么更适合植物miRNA靶基因挖掘？", "lncRNA如何通过染色质重塑复合物改变DNA甲基化和组蛋白状态？NONCODE和LNCipedia等数据库能提供哪些信息？", "circRNA为什么长期被忽视？它的四种生物合成途径、主要分类和生物学功能分别是什么？", "siRNA、piRNA、snoRNA和snRNA各自通过什么机制发挥作用？研究它们常用哪些数据库或软件？"]}, "appcards": [{"front": "为什么说“非编码RNA不编码蛋白质”这一说法并不绝对？请结合本章内容分析，并说明这对非编码RNA注释与功能研究提出了什么挑战。", "back": "1）传统定义：ncRNA指不编码蛋白质、直接在RNA水平发挥作用的RNA；细胞中含量最高的是rRNA和tRNA，广义ncRNA包括这两类，狭义通常不包括。2）例外现象：某些lncRNA可翻译蛋白质或多肽；果蝇大脑中发现大量circRNA翻译蛋白质或多肽。3）被忽视原因：对circRNA等新RNA了解太少，可能存在不同翻译机制；现有预测手段未很好预测其编码潜能。4）ORF相关：ORF可能存在于任何mRNA序列中，但很多ORF不翻译蛋白质；ORF越长翻译概率越大。5）挑战：ncRNA注释不能仅凭“不编码”一刀切，需要结合Ribo-Seq、质谱、保守性、ORF长度与翻译信号等综合判断；数据库注释也可能随研究深入而更新。", "points": "ncRNA定义；rRNA/tRNA归属；lncRNA可翻译；circRNA翻译；原因（了解少/机制不同/预测不足）；ORF与翻译概率；注释挑战", "mod": 0, "modName": "第七章 非编码RNA", "level": "掌握", "src": "生成"}, {"front": "请比较动物与植物miRNA在生物合成和靶基因调控方式上的主要差异，并说明为什么降解组测序更适合植物miRNA靶基因挖掘。", "back": "1）动物miRNA合成：miRNA基因转录生成pri-miRNA，细胞核内由Drosha及其辅因子DGCR8/Pasha加工成pre-miRNA，再由Exportin-5-RanGTP运输至细胞质；细胞质中Dicer与TRBP或PACT协同，将pre-miRNA加工为成熟miRNA，并组装RISC。2）植物miRNA合成：同样经历pri-miRNA到pre-miRNA再到成熟miRNA的过程，但加工酶和运输机制与动物存在差异，植物主要由DCL等参与。3）调控方式差异：动物miRNA对靶基因主要通过翻译抑制而不是切割进行调控；植物miRNA常通过切割靶mRNA发挥作用。4）降解组适用性：降解组测序可检测靶基因上的切割位点；动物以翻译抑制为主，降解组无法发现靶基因上的切割位点，因此该逆向挖掘技术只适合植物miRNA基因的大规模挖掘。5）补充：miRNA前体上由Dicer（动物）/DCL（植物）介导产生的切割信号可被降解组测序探测到，且切割信号位置与miRNA(5p)/miRNA*(-3p)边界高度相关，可作为寻找miRNA的线索。", "points": "动物pri-miRNA→Drosha/DGCR8→pre-miRNA→Exportin-5→Dicer/TRBP/PACT；植物DCL参与；动物翻译抑制；植物切割；降解组检测切割位点；动物不适合；前体切割信号", "mod": 0, "modName": "第七章 非编码RNA", "level": "掌握", "src": "生成"}, {"front": "circRNA为什么长期被忽视？请说明其结构特点、主要生物合成途径、分类和至少三种生物学功能。", "back": "1）结构特点：circRNA是以共价键形成闭环结构的内源性RNA，无5′端、3′端及polyA尾，因此经典polyA富集方法难以检测，长期被忽视。2）检测转机：高通量测序和生物信息学发展揭示其在真核生物中广泛存在。3）生物合成途径：①剪接体依赖途径：snRNP装配后，下游外显子5′供体位点与上游3′受体位点结合，促进环化；②内含子配对驱动：反向互补motif促进环化，5′剪接位点附近为7nt GU富集片段，分支位点附近为11nt C富集片段，供体-受体空间靠近推动成环；③套索驱动：外显子跳跃剪接产生套索副产物，被跳过区域经套索剪接形成外显子环状RNA；④其他途径。4）分类：外显子环状RNA（ecircRNA）、内含子环状RNA（ciRNA）、外显子-内含子环状RNA（EIciRNA）、反义链来源及基因间区来源环状RNA。5）定位与功能：ecircRNA主要定位细胞质，参与转录后调控；ciRNA和EIciRNA定位细胞核，调节亲本线性mRNA转录。主要功能包括：作为竞争性内源RNA（ceRNA）吸附miRNA；调控亲本基因转录；作为蛋白质支架或诱饵；翻译蛋白质或多肽等。", "points": "闭环、无5′/3′/polyA；polyA方法难检测；高通量测序；剪接体依赖；内含子配对；套索驱动；ecircRNA/ciRNA/EIciRNA；ceRNA；核内转录调控；翻译多肽", "mod": 0, "modName": "第七章 非编码RNA", "level": "掌握", "src": "生成"}, {"front": "某研究在植物中通过降解组测序发现一个候选miRNA可能切割某靶mRNA。请设计一个生物信息学分析流程，从序列获取到靶基因预测与切割位点验证，并说明关键数据库/软件的作用。", "back": "1）获取miRNA序列信息：使用miRBase（http://www.mirbase.org/），提供miRNA注册、序列查询、基因组定位、相关文献查询和靶基因预测等功能；当前版本涵盖多物种、发夹前体和成熟miRNA。2）miRNA新基因挖掘：利用降解组数据集和miRNA前体加工信号；对降解组数据预处理和归一化（RPM标准化），匹配转录物并保留精确匹配序列，分析降解组信号分布。识别规则：切割位点平均读数应是周围平均读数的5倍甚至更多；切割位点最高读数标记应映射在某个转录物种前12个最大丰度转录本之一等。3）前体加工信号：miRNA前体上由Dicer（动物）/DCL（植物）介导产生的切割信号可被降解组测序探测到，且切割信号位置与miRNA(5p)/miRNA*(-3p)边界高度相关，可作为寻找miRNA的线索。4）靶基因预测：使用psRNATarget等网站，提交小RNA序列或预加载转录本，设置期望值等参数，预测靶基因及结合位点。5）切割位点验证：利用降解组测序结果，查看靶基因上降解片段序列、匹配位置及测序计数；Perfect_match表示完全匹配，Degradome_sequence_count为支持该切割位点的读段数，5′_match_position等定位切割位点。6）综合判断：结合miRNA表达、靶基因表达负相关、切割位点信号强度和保守性等，降低假阳性。", "points": "miRBase获取序列；降解组预处理/RPM；切割位点5倍规则；前体加工信号；psRNATarget预测；Perfect_match；Degradome_sequence_count；5′_match_position；表达负相关", "mod": 0, "modName": "第七章 非编码RNA", "level": "掌握", "src": "生成"}]};